/**
 * Claude executor entrypoint — ABI-conformant.
 *
 * Reads ExecutorInput from environment variables, runs two-phase startup,
 * spawns `claude -p`, and writes ExecutorResult to result.json at RESULT_PATH.
 *
 * Formal ABI env vars (from ExecutorInput):
 *   TASK_ID, FEATURE_ID, WORKSPACE_ID, HANDLE
 *   TASK_REPO_URL, TASK_REPO_BRANCH, TASK_BASE_BRANCH
 *   EXECUTOR_WORKDIR, MGMT_REPO_URL
 *   RESULT_PATH, KIND (optional: impl|fix|reviewer|rebase — defaults to impl)
 *   BUDGET_TOKENS (optional)
 *   SSH_PRIVATE_KEY, GITHUB_TOKEN
 *
 * Derived paths (not passed by orchestrator — executor sets them in process.env):
 *   WORKSPACE_ROOT   = ${EXECUTOR_WORKDIR}/mgmt  (management repo clone, read-only)
 *   TASK_REPO_PATH   = ${EXECUTOR_WORKDIR}/impl  (implementation repo)
 *
 * Day-1 single-container extras (not in formal ABI — passed by SubProcessAdapter):
 *   TASK_BRANCH        — management repo feature branch for git commits
 *   GIT_AUTHOR_EMAIL   — for commit identity
 *   GIT_AUTHOR_NAME    — for commit identity
 *   WORKFLOW_LOCAL_PATH — workflow repo root for skills setup
 *   MAX_TURNS          — max claude CLI turns (default: 200)
 *   LOG_SINK_ENABLED   — "1" to flush JSONL log to management repo
 *   MCP_RAG_URL        — optional RAG server URL for MCP registration
 *   FIGMA_PERSONAL_ACCESS_TOKEN — optional Figma MCP
 *   GITNEXUS_MCP_URL   — optional GitNexus code-graph MCP server URL
 *   CLAUDE_AGENT_RUNTIME — injected as "1" for agent detection
 */

import { spawn, execSync } from "node:child_process";
import {
  mkdirSync,
  appendFileSync,
  readFileSync,
  writeFileSync,
  existsSync,
  readdirSync,
  rmSync,
  copyFileSync,
  lstatSync,
} from "node:fs";
import { join, dirname } from "node:path";
import { homedir } from "node:os";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { ExecutorResult } from "@workflow/runtime-abi";
import { isValidResult } from "@workflow/runtime-abi";
import { extractTokenUsage } from "./token-usage.js";
import { extractRagQueries } from "./rag-audit.js";
import { extractGitNexusQueries } from "./gitnexus-audit.js";
import { enforceInReviewRequiresPrUrl } from "./enforce-pr-url.js";
import { runRecovery, parseGitHubCoords, isMaxTurnsExit, type SpawnResult } from "./recovery.js";
import {
  generateContinuationBriefing,
  collectGitState,
  fetchOpenPrUrl,
} from "./briefing/continuation-context.js";
import { resolveSSHKey } from "./resolve-ssh-key.js";
import { redactSecrets } from "./redact-secrets.js";
import { buildGitEnv } from "./git-env.js";
import { flushLog } from "./flush-log.js";
import { ensureImplFeatureBranch } from "./impl-feature-branch.js";
import { setupGlobalSettings } from "./setup-global-settings.js";
import { buildBriefing, type BuildBriefingOpts, type BriefingKind } from "./briefing/index.js";

// ── Helpers ───────────────────────────────────────────────────────────────────

function requireEnv(name: string): string {
  const val = process.env[name];
  if (!val) throw new Error(`Required env var ${name} is not set`);
  return val;
}

function emit(event: Record<string, unknown>): void {
  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
}

/**
 * Materialize the implementation repo at taskRepoPath:
 *   - If path exists and origin matches URL: fetch + checkout + pull
 *   - Otherwise: clone fresh
 */
function materializeRepo(
  taskRepoUrl: string,
  taskRepoBranch: string,
  taskRepoPath: string,
  sshKeyPath: string | undefined,
): void {
  const env = buildGitEnv(sshKeyPath);
  const opts = { env, stdio: "pipe" as const };

  if (existsSync(join(taskRepoPath, ".git"))) {
    let originUrl = "";
    try {
      originUrl = execSync(`git -C "${taskRepoPath}" remote get-url origin`, {
        ...opts, encoding: "utf-8",
      }).trim();
    } catch { /* no remote — fall through to clone */ }

    if (originUrl === taskRepoUrl) {
      execSync(`git -C "${taskRepoPath}" fetch origin`, opts);
      // Discard local changes from a previous session before checkout.
      try { execSync(`git -C "${taskRepoPath}" checkout -- .`, opts); } catch { /* ignore */ }
      try {
        execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
      } catch {
        execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
      }
      try {
        execSync(
          `git -C "${taskRepoPath}" pull --ff-only origin "${taskRepoBranch}"`,
          opts,
        );
      } catch {
        emit({ type: "repo_pull_diverged", task_repo: taskRepoPath, branch: taskRepoBranch, note: "ff-only failed — working on checked-out ref without latest origin commits" });
      }
      return;
    }
  }

  // Clone fresh.
  mkdirSync(dirname(taskRepoPath), { recursive: true });
  if (existsSync(taskRepoPath)) {
    rmSync(taskRepoPath, { recursive: true, force: true });
  }
  execSync(`git clone "${taskRepoUrl}" "${taskRepoPath}"`, opts);
  try {
    execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
  } catch {
    execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
  }
}

/**
 * Materialize the management repo at mgmtDir on the task branch.
 * Idempotent: if the dir already contains a valid clone of the same URL,
 * runs fetch + checkout -B <taskBranch> origin/<taskBranch> instead of a fresh clone.
 * Falls back to main if the task branch doesn't exist on origin yet.
 */
function materializeMgmtRepo(
  mgmtRepoUrl: string,
  mgmtDir: string,
  sshKeyPath: string | undefined,
  taskBranch: string,
): void {
  const env = buildGitEnv(sshKeyPath);
  const opts = { env, stdio: "pipe" as const };

  const checkoutTaskBranch = (dir: string): void => {
    try {
      execSync(`git -C "${dir}" checkout -B "${taskBranch}" "origin/${taskBranch}"`, opts);
    } catch (taskBranchErr) {
      // Task branch not on origin yet — fall back to main.
      try {
        execSync(`git -C "${dir}" checkout main`, opts);
      } catch (mainCheckoutErr) {
        emit({ type: "mgmt_repo_checkout_failed", mgmt_dir: dir, branch: "main", details: String(mainCheckoutErr) });
      }
      try {
        execSync(`git -C "${dir}" pull --ff-only origin main`, opts);
      } catch {
        emit({ type: "mgmt_repo_pull_diverged", mgmt_dir: dir, note: "ff-only failed — using checked-out ref", task_branch_err: String(taskBranchErr) });
      }
    }
  };

  if (existsSync(join(mgmtDir, ".git"))) {
    let originUrl = "";
    try {
      originUrl = execSync(`git -C "${mgmtDir}" remote get-url origin`, {
        ...opts, encoding: "utf-8",
      }).trim();
    } catch { /* no remote — fall through to clone */ }

    if (originUrl === mgmtRepoUrl) {
      execSync(`git -C "${mgmtDir}" fetch origin`, opts);
      checkoutTaskBranch(mgmtDir);
      return;
    }
  }

  mkdirSync(dirname(mgmtDir), { recursive: true });
  if (existsSync(mgmtDir)) {
    rmSync(mgmtDir, { recursive: true, force: true });
  }
  execSync(`git clone "${mgmtRepoUrl}" "${mgmtDir}"`, opts);
  checkoutTaskBranch(mgmtDir);
}

/**
 * Turn budget for the E2 continuation retry — the focused re-spawn that runs
 * after a clean exit without result.json. Intentionally low: the retry's only
 * job is to write result.json based on existing branch state, not to do real
 * implementation work. Override via env var if you need more headroom.
 */
const DEFAULT_CONTINUATION_MAX_TURNS = 20;

const TOOLCHAIN_MARKERS: Array<{ file: string; tool: string }> = [
  { file: "yarn.lock",        tool: "yarn"    },
  { file: "pnpm-lock.yaml",   tool: "pnpm"    },
  { file: "bun.lockb",        tool: "bun"     },
  { file: "go.mod",           tool: "go"      },
  { file: "requirements.txt", tool: "python3" },
  { file: "pyproject.toml",   tool: "python3" },
  { file: "Cargo.toml",       tool: "cargo"   },
];

function checkRequiredTools(taskRepoPath: string): string[] {
  const missing: string[] = [];
  const checked = new Set<string>();
  for (const { file, tool } of TOOLCHAIN_MARKERS) {
    if (checked.has(tool)) continue;
    if (!existsSync(join(taskRepoPath, file))) continue;
    checked.add(tool);
    try {
      execSync(`which ${tool}`, { stdio: "pipe" });
    } catch {
      missing.push(tool);
    }
  }
  return missing;
}

function copyWorkspaceClaude(workspaceRoot: string): void {
  const src = join(workspaceRoot, "CLAUDE.md");
  if (!existsSync(src)) return;
  const destDir = join(homedir(), ".claude");
  mkdirSync(destDir, { recursive: true });
  copyFileSync(src, join(destDir, "CLAUDE.md"));
}

function copyDirRecursive(src: string, dest: string): void {
  mkdirSync(dest, { recursive: true });
  for (const entry of readdirSync(src)) {
    const srcPath = join(src, entry);
    const destPath = join(dest, entry);
    const stat = lstatSync(srcPath);
    if (stat.isDirectory()) {
      copyDirRecursive(srcPath, destPath);
    } else if (stat.isFile()) {
      copyFileSync(srcPath, destPath);
    }
  }
}

function setupGlobalSkills(workspaceRoot: string, workflowLocalPath: string): void {
  const globalSkillsDir = join(homedir(), ".claude", "skills");
  if (existsSync(globalSkillsDir)) {
    rmSync(globalSkillsDir, { recursive: true, force: true });
  }
  mkdirSync(globalSkillsDir, { recursive: true });

  const copySkillsFrom = (sourceDir: string): void => {
    if (!existsSync(sourceDir)) return;
    let entries: string[];
    try { entries = readdirSync(sourceDir); } catch { return; }
    for (const entry of entries) {
      const srcPath = join(sourceDir, entry);
      try {
        const stat = lstatSync(srcPath);
        if (!stat.isDirectory()) continue;
        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
      } catch (e) {
        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
      }
    }
  };

  copySkillsFrom(join(workflowLocalPath, "technical_skills"));
  copySkillsFrom(join(workflowLocalPath, "workflow_skills"));

  const wsSkillsDir = join(workspaceRoot, ".claude", "skills");
  if (existsSync(wsSkillsDir)) {
    let entries: string[];
    try { entries = readdirSync(wsSkillsDir); } catch { entries = []; }
    for (const entry of entries) {
      if (entry === ".gitignore") continue;
      const srcPath = join(wsSkillsDir, entry);
      try {
        const stat = lstatSync(srcPath);
        if (stat.isSymbolicLink() || !stat.isDirectory()) continue;
        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
      } catch (e) {
        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
      }
    }
  }
}

function writeResult(resultPath: string, result: ExecutorResult): void {
  mkdirSync(dirname(resultPath), { recursive: true });
  writeFileSync(resultPath, JSON.stringify(result), "utf-8");
}

// ── Main ──────────────────────────────────────────────────────────────────────

async function main(): Promise<void> {
  // ── Read formal ABI env vars ────────────────────────────────────────────────
  let taskId: string;
  let featureId: string;
  let taskRepoUrl: string;
  let taskRepoBranch: string;
  let executorWorkdir: string;
  let mgmtRepoUrl: string;
  let resultPath: string;
  let sshKeyPath: string | undefined;
  let githubToken: string;

  try {
    taskId = requireEnv("TASK_ID");
    featureId = requireEnv("FEATURE_ID");
    taskRepoUrl = requireEnv("TASK_REPO_URL");
    taskRepoBranch = requireEnv("TASK_REPO_BRANCH");
    executorWorkdir = requireEnv("EXECUTOR_WORKDIR");
    mgmtRepoUrl = requireEnv("MGMT_REPO_URL");
    resultPath = requireEnv("RESULT_PATH");
    githubToken = process.env.GITHUB_TOKEN ?? "";
    sshKeyPath = resolveSSHKey({ SSH_PRIVATE_KEY: process.env.SSH_PRIVATE_KEY }).sshKeyPath;
  } catch (e) {
    emit({ type: "executor_fatal", details: (e as Error).message });
    process.exit(1);
  }

  const budgetTokensStr = process.env.BUDGET_TOKENS;
  const budgetTokens = budgetTokensStr ? parseInt(budgetTokensStr, 10) : undefined;

  const implDir = join(executorWorkdir, "impl");
  const mgmtDir = join(executorWorkdir, "mgmt");

  // Day-1 single-container extras.
  const workspaceRoot = mgmtDir;
  const taskBranch = process.env.TASK_BRANCH ?? `feature/${featureId}-${taskId}`;
  const gitAuthorEmail = process.env.GIT_AUTHOR_EMAIL ?? "agent@unknown";
  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
  const workflowLocalPath = process.env.WORKFLOW_LOCAL_PATH ?? "";
  const maxTurns = parseInt(process.env.MAX_TURNS ?? "200", 10);
  const logSinkEnabled = process.env.LOG_SINK_ENABLED === "1";
  const mcpRagUrl = process.env.MCP_RAG_URL;
  const figmaToken = process.env.FIGMA_PERSONAL_ACCESS_TOKEN;
  const gitnexusMcpUrl = process.env.GITNEXUS_MCP_URL;
  const implementationModel = process.env.IMPLEMENTATION_MODEL;
  const executorKind = (process.env.EXECUTOR_KIND ?? "impl") as "impl" | "review";
  const implPrUrl = process.env.IMPL_PR_URL ?? "";
  const briefingKind = (process.env.KIND as BriefingKind | undefined) ??
    (executorKind === "review" ? "reviewer" : "impl");

  const runStartIso = new Date().toISOString();

  // ── 1. Two-phase repo materialization ─────────────────────────────────────
  // Phase 1: management repo — checked out to the task branch so $WORKSPACE_ROOT
  // has the current task YAML (on the task branch, not main).
  try {
    materializeMgmtRepo(mgmtRepoUrl, mgmtDir, sshKeyPath, taskBranch);
    process.env.WORKSPACE_ROOT = mgmtDir;
  } catch (e) {
    const details = `mgmt repo materialization failed: ${String(e)}`;
    emit({ type: "executor_fatal", task_id: taskId, details });
    writeResult(resultPath, {
      terminal_status: "failed",
      blocked_reason: `mgmt_repo_materialization_failed: ${String(e)}`,
    });
    process.exit(0);
  }

  // Phase 2: implementation repo
  const taskRepoBaseBranch = process.env.TASK_REPO_BASE_BRANCH ?? "";
  const taskBaseBranch = process.env.TASK_BASE_BRANCH ?? "";
  try {
    materializeRepo(taskRepoUrl, taskRepoBranch, implDir, sshKeyPath);
    process.env.TASK_REPO_PATH = implDir;
  } catch (e) {
    const details = `impl repo materialization failed: ${String(e)}`;
    emit({ type: "executor_fatal", task_id: taskId, details });
    writeResult(resultPath, {
      terminal_status: "failed",
      blocked_reason: `repo_materialization_failed: ${String(e)}`,
    });
    process.exit(0);
  }

  // Ensure `feature/{featureId}` exists on the impl repo remote so PR creation
  // can target it. Uses TASK_REPO_BASE_BRANCH (the repo's root base branch, e.g.
  // "main") as the push source — not TASK_BASE_BRANCH, which is the feature branch
  // itself and cannot be used as its own creation source.
  if (taskRepoBaseBranch) {
    ensureImplFeatureBranch(featureId, taskRepoBaseBranch, implDir, sshKeyPath, emit);
  }

  // ── 2. Toolchain pre-flight check ──────────────────────────────────────────
  const missingTools = checkRequiredTools(implDir);
  if (missingTools.length > 0) {
    const details = `missing tools: ${missingTools.join(", ")}`;
    emit({ type: "preflight_failed", task_id: taskId, feature_id: featureId, details });
    writeResult(resultPath, {
      terminal_status: "blocked",
      blocked_reason: "missing_tool",
      blocked_suggestion: `Install missing tools in the executor image: ${missingTools.join(", ")}`,
    });
    process.exit(0);
  }

  // ── 3. Workspace rules + global skills ─────────────────────────────────────
  if (workspaceRoot) copyWorkspaceClaude(workspaceRoot);
  if (workspaceRoot && workflowLocalPath) setupGlobalSkills(workspaceRoot, workflowLocalPath);
  if (workflowLocalPath) setupGlobalSettings(workflowLocalPath, emit);

  // ── 4. Build briefing (self-contained — reads workspace docs from mgmt repo) ──
  let briefingContent: string;
  try {
    const reviewCycleCount = parseInt(process.env.REVIEW_CYCLE_COUNT ?? "0", 10);
    const maxReviewCycles = parseInt(process.env.MAX_REVIEW_CYCLES ?? "3", 10);
    // Read task YAML from mgmt repo to resolve human-readable repo ID.
    let taskRepo = featureId;
    try {
      const taskYamlPath = join(mgmtDir, "docs", "features", featureId, "tasks", `${taskId}.yaml`);
      const taskYaml = parseYaml(readFileSync(taskYamlPath, "utf-8")) as Record<string, unknown>;
      if (typeof taskYaml["repo"] === "string") taskRepo = taskYaml["repo"];
    } catch { /* fall through to default */ }
    const baseOpts = {
      taskId,
      featureId,
      taskBranch,
      taskRepo,
      taskRepoRoot: implDir,
      workspaceRoot: mgmtDir,
      gitAuthorEmail,
      gitAuthorName,
      implementationModel: implementationModel ?? "claude-sonnet-4-6",
      resultPath,
    };
    let briefingOpts: BuildBriefingOpts;
    if (briefingKind === "reviewer") {
      briefingOpts = {
        kind: "reviewer",
        ...baseOpts,
        prUrl: implPrUrl,
        reviewerModel: implementationModel ?? "claude-sonnet-4-6",
        reviewCycleCount,
        maxReviewCycles,
      };
    } else if (briefingKind === "fix") {
      briefingOpts = {
        kind: "fix",
        ...baseOpts,
        prUrl: implPrUrl,
        mode: "review-fixes",
        reviewUrl: process.env.REVIEW_URL ?? "",
      };
    } else if (briefingKind === "rebase") {
      // Rebase dispatch uses the same fix-briefing infrastructure; mode is
      // forced to "conflict-resolution" inside buildBriefing.
      briefingOpts = {
        kind: "rebase",
        ...baseOpts,
        prUrl: implPrUrl,
        mode: "conflict-resolution",
        taskBaseBranch,
      };
    } else {
      briefingOpts = { kind: "impl", ...baseOpts };
    }
    briefingContent = buildBriefing(mgmtDir, briefingOpts);
  } catch (e) {
    emit({ type: "executor_fatal", task_id: taskId, details: `briefing build failed: ${String(e)}` });
    writeResult(resultPath, {
      terminal_status: "failed",
      blocked_reason: `briefing_build_failed: ${String(e)}`,
    });
    process.exit(0);
  }

  // Append hard-stop rule for missing tools.
  const effectiveBriefing =
    briefingContent +
    `\n\n## Hard stop rule — missing tools\nIf any shell command exits with code 127 ("command not found"), do NOT attempt to install it or work around it. Immediately write \`{"terminal_status":"blocked","blocked_reason":"missing_tool"}\` to \`${resultPath}\` and stop.`;

  // ── 5. Build MCP config ─────────────────────────────────────────────────────
  const mcpArgs: string[] = [];
  if (mcpRagUrl || figmaToken || gitnexusMcpUrl) {
    const mcpConfig: { mcpServers: Record<string, unknown> } = { mcpServers: {} };
    if (mcpRagUrl) {
      mcpConfig.mcpServers["rag-server"] = { type: "sse", url: `${mcpRagUrl}/sse` };
    }
    if (gitnexusMcpUrl) {
      mcpConfig.mcpServers["gitnexus"] = { type: "sse", url: `${gitnexusMcpUrl}/sse` };
    }
    if (figmaToken) {
      mcpConfig.mcpServers["figma"] = {
        type: "stdio",
        command: "npx",
        args: ["-y", "@figma/mcp-server"],
        env: { FIGMA_PERSONAL_ACCESS_TOKEN: figmaToken },
      };
    }
    const mcpConfigPath = `/tmp/mcp-config-${taskId}.json`;
    writeFileSync(mcpConfigPath, JSON.stringify(mcpConfig));
    mcpArgs.push("--mcp-config", mcpConfigPath);
  }

  if (mcpRagUrl) {
    emit({ type: "rag_mcp_registered", url: mcpRagUrl });
  } else {
    emit({ type: "rag_mcp_unavailable", reason: "MCP_RAG_URL not set" });
  }

  // ── 6. Spawn claude — wrapped in try/finally for Layer 1 recovery ───────────
  // PYTHONUSERBASE redirects all `pip install --user` into the executor's own
  // directory, preventing cross-executor pip registration conflicts when two
  // executors work on the same Python repo concurrently (e.g. T2 then T4 on cycle).
  const pybase = join(executorWorkdir, "pybase");
  const claudeEnv = {
    ...buildGitEnv(sshKeyPath),
    CLAUDE_AGENT_RUNTIME: "1",
    RESULT_PATH: resultPath,
    GITHUB_TOKEN: githubToken,
    TASK_REPO_PATH: implDir,
    PYTHONUSERBASE: pybase,
    PATH: `${join(pybase, "bin")}:${process.env.PATH ?? "/usr/local/bin:/usr/bin:/bin"}`,
  };

  /**
   * Spawn `claude -p` with the given briefing and turn limit. Captures stdout
   * into a buffer (also piped to this process's stdout) and installs a watchdog
   * that SIGTERMs the child 30s after it emits its final "result" event.
   */
  async function spawnClaude(briefing: string, turns: number): Promise<SpawnResult> {
    return await new Promise<SpawnResult>((resolve) => {
      const stdoutChunks: string[] = [];

      const child = spawn(
        "claude",
        [
          "-p", briefing,
          "--max-turns", String(turns),
          "--output-format", "stream-json",
          "--verbose",
          "--dangerously-skip-permissions",
          ...(implementationModel ? ["--model", implementationModel] : []),
          ...mcpArgs,
        ],
        { cwd: implDir, env: claudeEnv },
      );

      child.stdout.setEncoding("utf-8");
      child.stderr.setEncoding("utf-8");

      let resultWatchdog: ReturnType<typeof setTimeout> | null = null;
      let stdoutLineBuf = "";
      child.stdout.on("data", (chunk: string) => {
        stdoutChunks.push(chunk);
        process.stdout.write(chunk);
        if (resultWatchdog === null) {
          stdoutLineBuf += chunk;
          const lines = stdoutLineBuf.split("\n");
          stdoutLineBuf = lines.pop() ?? "";
          for (const line of lines) {
            if (line.includes('"type":"result"')) {
              resultWatchdog = setTimeout(() => {
                if (!child.killed) child.kill("SIGTERM");
              }, 30_000);
              break;
            }
          }
        }
      });

      child.stderr.on("data", (chunk: string) => {
        process.stderr.write(chunk);
      });

      child.on("error", (err: Error) => {
        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
        resolve({ stdout: stdoutChunks.join(""), status: null, signal: null, error: err });
      });

      child.on("exit", () => {
        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
        setTimeout(() => {
          if (!child.stdout.destroyed) child.stdout.destroy();
          if (!child.stderr.destroyed) child.stderr.destroy();
        }, 0);
      });

      child.on("close", (code: number | null, signal: string | null) => {
        resolve({ stdout: stdoutChunks.join(""), status: code, signal });
      });
    });
  }

  emit({ type: "claude_spawn", task_id: taskId, feature_id: featureId, max_turns: maxTurns });

  let spawnResult: SpawnResult | undefined;
  let tokenUsage: { input: number; output: number; model: string; cost_usd: number; pricingFallback: boolean } | undefined;
  let logFlushed = false;

  try {
    spawnResult = await spawnClaude(effectiveBriefing, maxTurns);

    emit({
      type: "claude_exit",
      task_id: taskId,
      feature_id: featureId,
      exit_code: spawnResult.status,
      signal: spawnResult.signal ?? null,
    });

    // ── 7. Token audit ────────────────────────────────────────────────────────
    tokenUsage = spawnResult.stdout ? extractTokenUsage(spawnResult.stdout) : undefined;

    if (tokenUsage === undefined) {
      emit({ type: "budget_audit_skipped", task_id: taskId, reason: "usage format not found" });
    } else {
      if (tokenUsage.pricingFallback) {
        emit({ type: "pricing_fallback", task_id: taskId, model: tokenUsage.model, note: "unknown model — Sonnet rates applied" });
      }
      emit({
        type: "budget_audit",
        task_id: taskId,
        feature_id: featureId,
        total_tokens: tokenUsage.input + tokenUsage.output,
        max_tokens: budgetTokens,
      });
    }

    // ── 7a. RAG query audit
    if (spawnResult.stdout) {
      for (const rq of extractRagQueries(spawnResult.stdout)) {
        emit({ type: "rag_query", ...rq });
      }
    }

    // ── 7b. GitNexus query audit
    if (spawnResult.stdout) {
      for (const gq of extractGitNexusQueries(spawnResult.stdout)) {
        emit({ type: "gitnexus_query", ...gq });
      }
    }

    // ── 8. Check for result.json written by Claude ────────────────────────────
    // The pr_url is sourced ONLY from Claude's result.json. The executor does not
    // scrape stdout for GitHub URLs, and does not synthesize an in_review result
    // when Claude exits cleanly without writing result.json — both paths previously
    // produced false-positives where unrelated PR URLs (e.g. the workspace claim PR
    // echoed via a Read of T<n>.yaml) were captured as the impl PR.

    /**
     * Read result.json, validate, apply pr_url enforcement + budget check, and
     * write the final version back. Returns true if a valid result was processed
     * (caller can return), false if no valid result.json exists.
     */
    const processResultJson = (stdout: string): boolean => {
      if (!existsSync(resultPath)) return false;
      let raw: unknown;
      try {
        raw = JSON.parse(readFileSync(resultPath, "utf-8"));
      } catch {
        return false;
      }
      if (!isValidResult(raw)) return false;

      let claudeResult = raw as ExecutorResult;
      if (tokenUsage !== undefined && !claudeResult.token_usage) {
        claudeResult.token_usage = { input: tokenUsage.input, output: tokenUsage.output, model: tokenUsage.model };
      }
      if (tokenUsage !== undefined && claudeResult.cost_usd === undefined) {
        claudeResult.cost_usd = tokenUsage.cost_usd;
      }

      // Refuse terminal_status: in_review without a valid pr_url. Checks:
      //   1. pr_url must be present and non-empty.
      //   2. pr_url owner/repo must match the task's implementation repo.
      //   3. PR head branch must be feature/{featureId}-{taskId} (API-verified).
      let prUrlCtx: Parameters<typeof enforceInReviewRequiresPrUrl>[1];
      try {
        const { owner, repo } = parseGitHubCoords(taskRepoUrl);
        prUrlCtx = { expectedOwner: owner, expectedRepo: repo, featureId, taskId, githubToken: githubToken || undefined };
      } catch {
        prUrlCtx = undefined;
      }
      const enforced = enforceInReviewRequiresPrUrl(claudeResult, prUrlCtx);
      if (enforced.rewritten) {
        emit({
          type: "in_review_refused_no_pr_url",
          task_id: taskId,
          feature_id: featureId,
          blocked_reason: enforced.result.blocked_reason,
        });
      }
      claudeResult = enforced.result;

      if (
        budgetTokens !== undefined &&
        tokenUsage !== undefined &&
        tokenUsage.input + tokenUsage.output > budgetTokens
      ) {
        writeResult(resultPath, {
          terminal_status: "blocked",
          blocked_reason: "budget_exceeded",
          token_usage: tokenUsage,
        });
      } else {
        writeResult(resultPath, claudeResult);
      }

      if (logSinkEnabled && workspaceRoot && taskBranch) {
        flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, stdout, claudeResult.terminal_status, sshKeyPath, emit);
        logFlushed = true;
      }
      return true;
    };

    if (processResultJson(spawnResult.stdout)) {
      // Valid result.json — Layer 1 recovery (finally block) will no-op.
      return;
    }

    // ── 9. Claude did not write result.json ──────────────────────────────────
    // Budget-exceeded: write blocked immediately (deterministic, no recovery side-effects needed).
    if (
      budgetTokens !== undefined &&
      tokenUsage !== undefined &&
      tokenUsage.input + tokenUsage.output > budgetTokens
    ) {
      writeResult(resultPath, {
        terminal_status: "blocked",
        blocked_reason: "budget_exceeded",
        token_usage: tokenUsage,
      });
      if (logSinkEnabled && workspaceRoot && taskBranch) {
        flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, "blocked", sshKeyPath, emit);
        logFlushed = true;
      }
      return;
    }

    // ── 9b. Continuation retry — Claude exited cleanly without writing result ─
    // The headless `-p` session can end on `end_turn` after a sub-skill completes
    // its declared steps, even though the outer skill still has work to do. Give
    // it one focused retry with a short briefing whose only job is to write
    // result.json. Skipped when the first run crashed, was signalled, or hit
    // max-turns — those failure modes won't be helped by another attempt.
    //
    // Review-kind executors have their own recovery path (recovery.recoverReview)
    // that checks GitHub for an already-posted review, so they don't need this.
    const continuationEligible =
      executorKind === "impl" &&
      spawnResult.status === 0 &&
      !spawnResult.signal &&
      !spawnResult.error &&
      !isMaxTurnsExit(spawnResult.stdout);

    if (continuationEligible) {
      const { commitsAhead, workingTreeStatus } = collectGitState(implDir, taskBaseBranch || "main");
      const existingPrUrl = fetchOpenPrUrl(taskRepoUrl, taskRepoBranch, githubToken);

      const continuationBriefing = generateContinuationBriefing({
        taskId,
        featureId,
        taskBranch: taskRepoBranch,
        taskRepoRoot: implDir,
        resultPath,
        taskBaseBranch: taskBaseBranch || "main",
        prUrl: existingPrUrl,
        commitsAhead,
        workingTreeStatus,
      });

      emit({
        type: "executor_continuation_retry",
        task_id: taskId,
        feature_id: featureId,
        had_pr_url: Boolean(existingPrUrl),
      });

      const retryMaxTurns = parseInt(
        process.env.CONTINUATION_MAX_TURNS ?? String(DEFAULT_CONTINUATION_MAX_TURNS),
        10,
      );
      const retryResult = await spawnClaude(continuationBriefing, retryMaxTurns);

      emit({
        type: "executor_continuation_complete",
        task_id: taskId,
        feature_id: featureId,
        exit_code: retryResult.status,
        signal: retryResult.signal ?? null,
      });

      // Replace spawnResult so post-hoc recovery (if needed) uses the latest state
      // for handover.md and emit. tokenUsage is re-extracted from the retry stdout
      // and added to the first-run usage so the audit reflects total tokens spent.
      // Preserve first-run stdout — flushLog and recovery use it for forensics.
      // Concatenate first-run + retry stdout with a separator so the log sink
      // captures both. The retry's stdout alone is the recovery / continuation
      // tail; the first run's is where the real work happened.
      const firstRunStdout = spawnResult.stdout;
      spawnResult = {
        ...retryResult,
        stdout: firstRunStdout + "\n--- continuation retry stdout ---\n" + retryResult.stdout,
      };
      const retryUsage = retryResult.stdout ? extractTokenUsage(retryResult.stdout) : undefined;
      if (retryUsage !== undefined) {
        if (tokenUsage !== undefined) {
          // Sum input/output/cost; keep first-run model when both runs used
          // the same model (the common case). If models differ, emit a
          // pricing_fallback-style warning and use the retry's model so the
          // audit reflects the most-recent run. pricingFallback is true if
          // either run hit it.
          if (tokenUsage.model !== retryUsage.model) {
            emit({
              type: "continuation_model_mismatch",
              task_id: taskId,
              feature_id: featureId,
              first_run_model: tokenUsage.model,
              retry_model: retryUsage.model,
              note: "retry used a different model than first run — audit reflects retry's model",
            });
          }
          tokenUsage = {
            input: tokenUsage.input + retryUsage.input,
            output: tokenUsage.output + retryUsage.output,
            model: tokenUsage.model === retryUsage.model ? tokenUsage.model : retryUsage.model,
            cost_usd: tokenUsage.cost_usd + retryUsage.cost_usd,
            pricingFallback: tokenUsage.pricingFallback || retryUsage.pricingFallback,
          };
        } else {
          tokenUsage = retryUsage;
        }
      }

      if (processResultJson(retryResult.stdout)) {
        emit({ type: "executor_continuation_recovered", task_id: taskId, feature_id: featureId });
        return;
      }

      emit({ type: "executor_continuation_failed", task_id: taskId, feature_id: featureId,
             note: "retry exited without writing result.json — falling through to post-hoc recovery" });
    }

    // No result.json produced — recovery will write one in the finally block.

  } finally {
    // ── Layer 1: post-hoc recovery ────────────────────────────────────────────
    // Runs regardless of how the spawn ended. No-op when result.json has a
    // valid in_review result (Claude finished cleanly). Otherwise: commits
    // uncommitted work, pushes, opens a draft PR, writes handover.md, and
    // writes a blocked result.json.
    await runRecovery({
      spawnResult,
      taskId,
      featureId,
      taskRepoBranch,
      taskRepoPath: implDir,
      taskRepoUrl,
      githubToken,
      sshKeyPath,
      gitAuthorEmail,
      gitAuthorName,
      resultPath,
      tokenUsage: tokenUsage ? { input: tokenUsage.input, output: tokenUsage.output } : undefined,
      kind: executorKind,
      implPrUrl: implPrUrl || undefined,
      taskBaseBranch: taskBaseBranch || undefined,
    });

    // Flush log after recovery (best-effort, uses result.json to determine outcome).
    // Skip if already flushed in the success or budget-exceeded paths above.
    if (!logFlushed && logSinkEnabled && workspaceRoot && taskBranch) {
      let outcome = "unknown";
      try {
        const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as ExecutorResult;
        outcome = raw.terminal_status;
      } catch { /* ignore */ }
      flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult?.stdout ?? "", outcome, sshKeyPath, emit);
    }
  }
}


main().catch((e) => {
  try {
    console.log(JSON.stringify({ type: "fatal_error", details: String(e), at: new Date().toISOString() }));
  } catch { /* last resort */ }
  process.exit(1);
});

/**
 * Claude executor entrypoint — ABI-conformant.
 *
 * Reads ExecutorInput from environment variables, runs two-phase startup,
 * spawns `claude -p`, and writes ExecutorResult to result.json at RESULT_PATH.
 *
 * Formal ABI env vars (from ExecutorInput):
 *   TASK_ID, FEATURE_ID, WORKSPACE_ID, HANDLE
 *   TASK_REPO_URL, TASK_REPO_BRANCH, TASK_BASE_BRANCH
 *   EXECUTOR_WORKDIR, MGMT_REPO_URL
 *   RESULT_PATH, KIND (optional: impl|fix|reviewer|rebase — defaults to impl)
 *   BUDGET_TOKENS (optional)
 *   SSH_PRIVATE_KEY, GITHUB_TOKEN
 *
 * Derived paths (not passed by orchestrator — executor sets them in process.env):
 *   WORKSPACE_ROOT   = ${EXECUTOR_WORKDIR}/mgmt  (management repo clone, read-only)
 *   TASK_REPO_PATH   = ${EXECUTOR_WORKDIR}/impl  (implementation repo)
 *
 * Day-1 single-container extras (not in formal ABI — passed by SubProcessAdapter):
 *   TASK_BRANCH        — management repo feature branch for git commits
 *   GIT_AUTHOR_EMAIL   — for commit identity
 *   GIT_AUTHOR_NAME    — for commit identity
 *   WORKFLOW_LOCAL_PATH — workflow repo root for skills setup
 *   MAX_TURNS          — max claude CLI turns (default: 200)
 *   LOG_SINK_ENABLED   — "1" to flush JSONL log to management repo
 *   MCP_RAG_URL        — optional RAG server URL for MCP registration
 *   FIGMA_PERSONAL_ACCESS_TOKEN — optional Figma MCP
 *   GITNEXUS_MCP_URL   — optional GitNexus code-graph MCP server URL
 *   AGENT_RUNTIME — injected as "1" for agent detection
 */

import { spawn, execSync } from "node:child_process";
import {
  mkdirSync,
  appendFileSync,
  readFileSync,
  writeFileSync,
  existsSync,
  readdirSync,
  rmSync,
  copyFileSync,
  lstatSync,
} from "node:fs";
import { join, dirname } from "node:path";
import { homedir } from "node:os";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { ExecutorResult } from "@workflow/runtime-abi";
import { isValidResult } from "@workflow/runtime-abi";
import { extractTokenUsage } from "./token-usage.js";
import { extractRagQueries } from "./rag-audit.js";
import { extractGitNexusQueries } from "./gitnexus-audit.js";
import { enforceInReviewRequiresPrUrl } from "./enforce-pr-url.js";
import { runRecovery, parseGitHubCoords, isMaxTurnsExit, type SpawnResult } from "./recovery.js";
import {
  generateContinuationBriefing,
  collectGitState,
  fetchOpenPrUrl,
} from "./briefing/continuation-context.js";
import { resolveSSHKey } from "./resolve-ssh-key.js";
import { redactSecrets } from "./redact-secrets.js";
import { buildGitEnv } from "./git-env.js";
import { flushLog } from "./flush-log.js";
import { ensureImplFeatureBranch } from "./impl-feature-branch.js";
import { setupGlobalSettings } from "./setup-global-settings.js";
import { buildBriefing, type BuildBriefingOpts, type BriefingKind } from "./briefing/index.js";

// ── Helpers ───────────────────────────────────────────────────────────────────

function requireEnv(name: string): string {
  const val = process.env[name];
  if (!val) throw new Error(`Required env var ${name} is not set`);
  return val;
}

function emit(event: Record<string, unknown>): void {
  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
}

/**
 * Materialize the implementation repo at taskRepoPath:
 *   - If path exists and origin matches URL: fetch + checkout + pull
 *   - Otherwise: clone fresh
 */
function materializeRepo(
  taskRepoUrl: string,
  taskRepoBranch: string,
  taskRepoPath: string,
  sshKeyPath: string | undefined,
): void {
  const env = buildGitEnv(sshKeyPath);
  const opts = { env, stdio: "pipe" as const };

  if (existsSync(join(taskRepoPath, ".git"))) {
    let originUrl = "";
    try {
      originUrl = execSync(`git -C "${taskRepoPath}" remote get-url origin`, {
        ...opts, encoding: "utf-8",
      }).trim();
    } catch { /* no remote — fall through to clone */ }

    if (originUrl === taskRepoUrl) {
      execSync(`git -C "${taskRepoPath}" fetch origin`, opts);
      // Discard local changes from a previous session before checkout.
      try { execSync(`git -C "${taskRepoPath}" checkout -- .`, opts); } catch { /* ignore */ }
      try {
        execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
      } catch {
        execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
      }
      try {
        execSync(
          `git -C "${taskRepoPath}" pull --ff-only origin "${taskRepoBranch}"`,
          opts,
        );
      } catch {
        emit({ type: "repo_pull_diverged", task_repo: taskRepoPath, branch: taskRepoBranch, note: "ff-only failed — working on checked-out ref without latest origin commits" });
      }
      return;
    }
  }

  // Clone fresh.
  mkdirSync(dirname(taskRepoPath), { recursive: true });
  if (existsSync(taskRepoPath)) {
    rmSync(taskRepoPath, { recursive: true, force: true });
  }
  execSync(`git clone "${taskRepoUrl}" "${taskRepoPath}"`, opts);
  try {
    execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
  } catch {
    execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
  }
}

/**
 * Materialize the management repo at mgmtDir on the task branch.
 * Idempotent: if the dir already contains a valid clone of the same URL,
 * runs fetch + checkout -B <taskBranch> origin/<taskBranch> instead of a fresh clone.
 * Falls back to main if the task branch doesn't exist on origin yet.
 */
function materializeMgmtRepo(
  mgmtRepoUrl: string,
  mgmtDir: string,
  sshKeyPath: string | undefined,
  taskBranch: string,
): void {
  const env = buildGitEnv(sshKeyPath);
  const opts = { env, stdio: "pipe" as const };

  const checkoutTaskBranch = (dir: string): void => {
    try {
      execSync(`git -C "${dir}" checkout -B "${taskBranch}" "origin/${taskBranch}"`, opts);
    } catch (taskBranchErr) {
      // Task branch not on origin yet — fall back to main.
      try {
        execSync(`git -C "${dir}" checkout main`, opts);
      } catch (mainCheckoutErr) {
        emit({ type: "mgmt_repo_checkout_failed", mgmt_dir: dir, branch: "main", details: String(mainCheckoutErr) });
      }
      try {
        execSync(`git -C "${dir}" pull --ff-only origin main`, opts);
      } catch {
        emit({ type: "mgmt_repo_pull_diverged", mgmt_dir: dir, note: "ff-only failed — using checked-out ref", task_branch_err: String(taskBranchErr) });
      }
    }
  };

  if (existsSync(join(mgmtDir, ".git"))) {
    let originUrl = "";
    try {
      originUrl = execSync(`git -C "${mgmtDir}" remote get-url origin`, {
        ...opts, encoding: "utf-8",
      }).trim();
    } catch { /* no remote — fall through to clone */ }

    if (originUrl === mgmtRepoUrl) {
      execSync(`git -C "${mgmtDir}" fetch origin`, opts);
      checkoutTaskBranch(mgmtDir);
      return;
    }
  }

  mkdirSync(dirname(mgmtDir), { recursive: true });
  if (existsSync(mgmtDir)) {
    rmSync(mgmtDir, { recursive: true, force: true });
  }
  execSync(`git clone "${mgmtRepoUrl}" "${mgmtDir}"`, opts);
  checkoutTaskBranch(mgmtDir);
}

/**
 * Turn budget for the E2 continuation retry — the focused re-spawn that runs
 * after a clean exit without result.json. Intentionally low: the retry's only
 * job is to write result.json based on existing branch state, not to do real
 * implementation work. Override via env var if you need more headroom.
 */
const DEFAULT_CONTINUATION_MAX_TURNS = 20;

const TOOLCHAIN_MARKERS: Array<{ file: string; tool: string }> = [
  { file: "yarn.lock",        tool: "yarn"    },
  { file: "pnpm-lock.yaml",   tool: "pnpm"    },
  { file: "bun.lockb",        tool: "bun"     },
  { file: "go.mod",           tool: "go"      },
  { file: "requirements.txt", tool: "python3" },
  { file: "pyproject.toml",   tool: "python3" },
  { file: "Cargo.toml",       tool: "cargo"   },
];

function checkRequiredTools(taskRepoPath: string): string[] {
  const missing: string[] = [];
  const checked = new Set<string>();
  for (const { file, tool } of TOOLCHAIN_MARKERS) {
    if (checked.has(tool)) continue;
    if (!existsSync(join(taskRepoPath, file))) continue;
    checked.add(tool);
    try {
      execSync(`which ${tool}`, { stdio: "pipe" });
    } catch {
      missing.push(tool);
    }
  }
  return missing;
}

function copyWorkspaceClaude(workspaceRoot: string): void {
  const src = join(workspaceRoot, "CLAUDE.md");
  if (!existsSync(src)) return;
  const destDir = join(homedir(), ".claude");
  mkdirSync(destDir, { recursive: true });
  copyFileSync(src, join(destDir, "CLAUDE.md"));
}

function copyDirRecursive(src: string, dest: string): void {
  mkdirSync(dest, { recursive: true });
  for (const entry of readdirSync(src)) {
    const srcPath = join(src, entry);
    const destPath = join(dest, entry);
    const stat = lstatSync(srcPath);
    if (stat.isDirectory()) {
      copyDirRecursive(srcPath, destPath);
    } else if (stat.isFile()) {
      copyFileSync(srcPath, destPath);
    }
  }
}

function setupGlobalSkills(workspaceRoot: string, workflowLocalPath: string): void {
  const globalSkillsDir = join(homedir(), ".claude", "skills");
  if (existsSync(globalSkillsDir)) {
    rmSync(globalSkillsDir, { recursive: true, force: true });
  }
  mkdirSync(globalSkillsDir, { recursive: true });

  const copySkillsFrom = (sourceDir: string): void => {
    if (!existsSync(sourceDir)) return;
    let entries: string[];
    try { entries = readdirSync(sourceDir); } catch { return; }
    for (const entry of entries) {
      const srcPath = join(sourceDir, entry);
      try {
        const stat = lstatSync(srcPath);
        if (!stat.isDirectory()) continue;
        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
      } catch (e) {
        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
      }
    }
  };

  copySkillsFrom(join(workflowLocalPath, "technical_skills"));
  copySkillsFrom(join(workflowLocalPath, "workflow_skills"));

  const wsSkillsDir = join(workspaceRoot, ".claude", "skills");
  if (existsSync(wsSkillsDir)) {
    let entries: string[];
    try { entries = readdirSync(wsSkillsDir); } catch { entries = []; }
    for (const entry of entries) {
      if (entry === ".gitignore") continue;
      const srcPath = join(wsSkillsDir, entry);
      try {
        const stat = lstatSync(srcPath);
        if (stat.isSymbolicLink() || !stat.isDirectory()) continue;
        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
      } catch (e) {
        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
      }
    }
  }
}

function writeResult(resultPath: string, result: ExecutorResult): void {
  mkdirSync(dirname(resultPath), { recursive: true });
  writeFileSync(resultPath, JSON.stringify(result), "utf-8");
}

// ── Main ──────────────────────────────────────────────────────────────────────

async function main(): Promise<void> {
  // ── Read formal ABI env vars ────────────────────────────────────────────────
  let taskId: string;
  let featureId: string;
  let taskRepoUrl: string;
  let taskRepoBranch: string;
  let executorWorkdir: string;
  let mgmtRepoUrl: string;
  let resultPath: string;
  let sshKeyPath: string | undefined;
  let githubToken: string;

  try {
    taskId = requireEnv("TASK_ID");
    featureId = requireEnv("FEATURE_ID");
    taskRepoUrl = requireEnv("TASK_REPO_URL");
    taskRepoBranch = requireEnv("TASK_REPO_BRANCH");
    executorWorkdir = requireEnv("EXECUTOR_WORKDIR");
    mgmtRepoUrl = requireEnv("MGMT_REPO_URL");
    resultPath = requireEnv("RESULT_PATH");
    githubToken = process.env.GITHUB_TOKEN ?? "";
    sshKeyPath = resolveSSHKey({ SSH_PRIVATE_KEY: process.env.SSH_PRIVATE_KEY }).sshKeyPath;
  } catch (e) {
    emit({ type: "executor_fatal", details: (e as Error).message });
    process.exit(1);
  }

  const budgetTokensStr = process.env.BUDGET_TOKENS;
  const budgetTokens = budgetTokensStr ? parseInt(budgetTokensStr, 10) : undefined;

  const implDir = join(executorWorkdir, "impl");
  const mgmtDir = join(executorWorkdir, "mgmt");

  // Day-1 single-container extras.
  const workspaceRoot = mgmtDir;
  const taskBranch = process.env.TASK_BRANCH ?? `feature/${featureId}-${taskId}`;
  const gitAuthorEmail = process.env.GIT_AUTHOR_EMAIL ?? "agent@unknown";
  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
  const workflowLocalPath = process.env.WORKFLOW_LOCAL_PATH ?? "";
  const maxTurns = parseInt(process.env.MAX_TURNS ?? "200", 10);
  const logSinkEnabled = process.env.LOG_SINK_ENABLED === "1";
  const mcpRagUrl = process.env.MCP_RAG_URL;
  const figmaToken = process.env.FIGMA_PERSONAL_ACCESS_TOKEN;
  const gitnexusMcpUrl = process.env.GITNEXUS_MCP_URL;
  const implementationModel = process.env.IMPLEMENTATION_MODEL;
  const executorKind = (process.env.EXECUTOR_KIND ?? "impl") as "impl" | "review";
  const implPrUrl = process.env.IMPL_PR_URL ?? "";
  const briefingKind = (process.env.KIND as BriefingKind | undefined) ??
    (executorKind === "review" ? "reviewer" : "impl");

  const runStartIso = new Date().toISOString();

  // ── 1. Two-phase repo materialization ─────────────────────────────────────
  // Phase 1: management repo — checked out to the task branch so $WORKSPACE_ROOT
  // has the current task YAML (on the task branch, not main).
  try {
    materializeMgmtRepo(mgmtRepoUrl, mgmtDir, sshKeyPath, taskBranch);
    process.env.WORKSPACE_ROOT = mgmtDir;
  } catch (e) {
    const details = `mgmt repo materialization failed: ${String(e)}`;
    emit({ type: "executor_fatal", task_id: taskId, details });
    writeResult(resultPath, {
      terminal_status: "failed",
      blocked_reason: `mgmt_repo_materialization_failed: ${String(e)}`,
    });
    process.exit(0);
  }

  // Phase 2: implementation repo
  const taskRepoBaseBranch = process.env.TASK_REPO_BASE_BRANCH ?? "";
  const taskBaseBranch = process.env.TASK_BASE_BRANCH ?? "";
  try {
    materializeRepo(taskRepoUrl, taskRepoBranch, implDir, sshKeyPath);
    process.env.TASK_REPO_PATH = implDir;
  } catch (e) {
    const details = `impl repo materialization failed: ${String(e)}`;
    emit({ type: "executor_fatal", task_id: taskId, details });
    writeResult(resultPath, {
      terminal_status: "failed",
      blocked_reason: `repo_materialization_failed: ${String(e)}`,
    });
    process.exit(0);
  }

  // Ensure `feature/{featureId}` exists on the impl repo remote so PR creation
  // can target it. Uses TASK_REPO_BASE_BRANCH (the repo's root base branch, e.g.
  // "main") as the push source — not TASK_BASE_BRANCH, which is the feature branch
  // itself and cannot be used as its own creation source.
  if (taskRepoBaseBranch) {
    ensureImplFeatureBranch(featureId, taskRepoBaseBranch, implDir, sshKeyPath, emit);
  }

  // ── 2. Toolchain pre-flight check ──────────────────────────────────────────
  const missingTools = checkRequiredTools(implDir);
  if (missingTools.length > 0) {
    const details = `missing tools: ${missingTools.join(", ")}`;
    emit({ type: "preflight_failed", task_id: taskId, feature_id: featureId, details });
    writeResult(resultPath, {
      terminal_status: "blocked",
      blocked_reason: "missing_tool",
      blocked_suggestion: `Install missing tools in the executor image: ${missingTools.join(", ")}`,
    });
    process.exit(0);
  }

  // ── 3. Workspace rules + global skills ─────────────────────────────────────
  if (workspaceRoot) copyWorkspaceClaude(workspaceRoot);
  if (workspaceRoot && workflowLocalPath) setupGlobalSkills(workspaceRoot, workflowLocalPath);
  if (workflowLocalPath) setupGlobalSettings(workflowLocalPath, emit);

  // ── 4. Build briefing (self-contained — reads workspace docs from mgmt repo) ──
  let briefingContent: string;
  try {
    const reviewCycleCount = parseInt(process.env.REVIEW_CYCLE_COUNT ?? "0", 10);
    const maxReviewCycles = parseInt(process.env.MAX_REVIEW_CYCLES ?? "3", 10);
    // Read task YAML from mgmt repo to resolve human-readable repo ID.
    let taskRepo = featureId;
    try {
      const taskYamlPath = join(mgmtDir, "docs", "features", featureId, "tasks", `${taskId}.yaml`);
      const taskYaml = parseYaml(readFileSync(taskYamlPath, "utf-8")) as Record<string, unknown>;
      if (typeof taskYaml["repo"] === "string") taskRepo = taskYaml["repo"];
    } catch { /* fall through to default */ }
    const baseOpts = {
      taskId,
      featureId,
      taskBranch,
      taskRepo,
      taskRepoRoot: implDir,
      workspaceRoot: mgmtDir,
      gitAuthorEmail,
      gitAuthorName,
      implementationModel: implementationModel ?? "claude-sonnet-4-6",
      resultPath,
    };
    let briefingOpts: BuildBriefingOpts;
    if (briefingKind === "reviewer") {
      briefingOpts = {
        kind: "reviewer",
        ...baseOpts,
        prUrl: implPrUrl,
        reviewerModel: implementationModel ?? "claude-sonnet-4-6",
        reviewCycleCount,
        maxReviewCycles,
      };
    } else if (briefingKind === "fix") {
      briefingOpts = {
        kind: "fix",
        ...baseOpts,
        prUrl: implPrUrl,
        mode: "review-fixes",
        reviewUrl: process.env.REVIEW_URL ?? "",
      };
    } else if (briefingKind === "rebase") {
      // Rebase dispatch uses the same fix-briefing infrastructure; mode is
      // forced to "conflict-resolution" inside buildBriefing.
      briefingOpts = {
        kind: "rebase",
        ...baseOpts,
        prUrl: implPrUrl,
        mode: "conflict-resolution",
        taskBaseBranch,
      };
    } else {
      briefingOpts = { kind: "impl", ...baseOpts };
    }
    briefingContent = buildBriefing(mgmtDir, briefingOpts);
  } catch (e) {
    emit({ type: "executor_fatal", task_id: taskId, details: `briefing build failed: ${String(e)}` });
    writeResult(resultPath, {
      terminal_status: "failed",
      blocked_reason: `briefing_build_failed: ${String(e)}`,
    });
    process.exit(0);
  }

  // Append hard-stop rule for missing tools.
  const effectiveBriefing =
    briefingContent +
    `\n\n## Hard stop rule — missing tools\nIf any shell command exits with code 127 ("command not found"), do NOT attempt to install it or work around it. Immediately write \`{"terminal_status":"blocked","blocked_reason":"missing_tool"}\` to \`${resultPath}\` and stop.`;

  // ── 5. Build MCP config ─────────────────────────────────────────────────────
  const mcpArgs: string[] = [];
  if (mcpRagUrl || figmaToken || gitnexusMcpUrl) {
    const mcpConfig: { mcpServers: Record<string, unknown> } = { mcpServers: {} };
    if (mcpRagUrl) {
      mcpConfig.mcpServers["rag-server"] = { type: "sse", url: `${mcpRagUrl}/sse` };
    }
    if (gitnexusMcpUrl) {
      mcpConfig.mcpServers["gitnexus"] = { type: "sse", url: `${gitnexusMcpUrl}/sse` };
    }
    if (figmaToken) {
      mcpConfig.mcpServers["figma"] = {
        type: "stdio",
        command: "npx",
        args: ["-y", "@figma/mcp-server"],
        env: { FIGMA_PERSONAL_ACCESS_TOKEN: figmaToken },
      };
    }
    const mcpConfigPath = `/tmp/mcp-config-${taskId}.json`;
    writeFileSync(mcpConfigPath, JSON.stringify(mcpConfig));
    mcpArgs.push("--mcp-config", mcpConfigPath);
  }

  if (mcpRagUrl) {
    emit({ type: "rag_mcp_registered", url: mcpRagUrl });
  } else {
    emit({ type: "rag_mcp_unavailable", reason: "MCP_RAG_URL not set" });
  }

  // ── 6. Spawn claude — wrapped in try/finally for Layer 1 recovery ───────────
  // PYTHONUSERBASE redirects all `pip install --user` into the executor's own
  // directory, preventing cross-executor pip registration conflicts when two
  // executors work on the same Python repo concurrently (e.g. T2 then T4 on cycle).
  const pybase = join(executorWorkdir, "pybase");
  const claudeEnv = {
    ...buildGitEnv(sshKeyPath),
    CLAUDE_AGENT_RUNTIME: "1",
    RESULT_PATH: resultPath,
    GITHUB_TOKEN: githubToken,
    TASK_REPO_PATH: implDir,
    PYTHONUSERBASE: pybase,
    PATH: `${join(pybase, "bin")}:${process.env.PATH ?? "/usr/local/bin:/usr/bin:/bin"}`,
  };

  /**
   * Spawn `claude -p` with the given briefing and turn limit. Captures stdout
   * into a buffer (also piped to this process's stdout) and installs a watchdog
   * that SIGTERMs the child 30s after it emits its final "result" event.
   */
  async function spawnClaude(briefing: string, turns: number): Promise<SpawnResult> {
    return await new Promise<SpawnResult>((resolve) => {
      const stdoutChunks: string[] = [];

      const child = spawn(
        "claude",
        [
          "-p", briefing,
          "--max-turns", String(turns),
          "--output-format", "stream-json",
          "--verbose",
          "--dangerously-skip-permissions",
          ...(implementationModel ? ["--model", implementationModel] : []),
          ...mcpArgs,
        ],
        { cwd: implDir, env: claudeEnv },
      );

      child.stdout.setEncoding("utf-8");
      child.stderr.setEncoding("utf-8");

      let resultWatchdog: ReturnType<typeof setTimeout> | null = null;
      let stdoutLineBuf = "";
      child.stdout.on("data", (chunk: string) => {
        stdoutChunks.push(chunk);
        process.stdout.write(chunk);
        if (resultWatchdog === null) {
          stdoutLineBuf += chunk;
          const lines = stdoutLineBuf.split("\n");
          stdoutLineBuf = lines.pop() ?? "";
          for (const line of lines) {
            if (line.includes('"type":"result"')) {
              resultWatchdog = setTimeout(() => {
                if (!child.killed) child.kill("SIGTERM");
              }, 30_000);
              break;
            }
          }
        }
      });

      child.stderr.on("data", (chunk: string) => {
        process.stderr.write(chunk);
      });

      child.on("error", (err: Error) => {
        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
        resolve({ stdout: stdoutChunks.join(""), status: null, signal: null, error: err });
      });

      child.on("exit", () => {
        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
        setTimeout(() => {
          if (!child.stdout.destroyed) child.stdout.destroy();
          if (!child.stderr.destroyed) child.stderr.destroy();
        }, 0);
      });

      child.on("close", (code: number | null, signal: string | null) => {
        resolve({ stdout: stdoutChunks.join(""), status: code, signal });
      });
    });
  }

  emit({ type: "claude_spawn", task_id: taskId, feature_id: featureId, max_turns: maxTurns });

  let spawnResult: SpawnResult | undefined;
  let tokenUsage: { input: number; output: number; model: string; cost_usd: number; pricingFallback: boolean } | undefined;
  let logFlushed = false;

  try {
    spawnResult = await spawnClaude(effectiveBriefing, maxTurns);

    emit({
      type: "claude_exit",
      task_id: taskId,
      feature_id: featureId,
      exit_code: spawnResult.status,
      signal: spawnResult.signal ?? null,
    });

    // ── 7. Token audit ────────────────────────────────────────────────────────
    tokenUsage = spawnResult.stdout ? extractTokenUsage(spawnResult.stdout) : undefined;

    if (tokenUsage === undefined) {
      emit({ type: "budget_audit_skipped", task_id: taskId, reason: "usage format not found" });
    } else {
      if (tokenUsage.pricingFallback) {
        emit({ type: "pricing_fallback", task_id: taskId, model: tokenUsage.model, note: "unknown model — Sonnet rates applied" });
      }
      emit({
        type: "budget_audit",
        task_id: taskId,
        feature_id: featureId,
        total_tokens: tokenUsage.input + tokenUsage.output,
        max_tokens: budgetTokens,
      });
    }

    // ── 7a. RAG query audit
    if (spawnResult.stdout) {
      for (const rq of extractRagQueries(spawnResult.stdout)) {
        emit({ type: "rag_query", ...rq });
      }
    }

    // ── 7b. GitNexus query audit
    if (spawnResult.stdout) {
      for (const gq of extractGitNexusQueries(spawnResult.stdout)) {
        emit({ type: "gitnexus_query", ...gq });
      }
    }

    // ── 8. Check for result.json written by Claude ────────────────────────────
    // The pr_url is sourced ONLY from Claude's result.json. The executor does not
    // scrape stdout for GitHub URLs, and does not synthesize an in_review result
    // when Claude exits cleanly without writing result.json — both paths previously
    // produced false-positives where unrelated PR URLs (e.g. the workspace claim PR
    // echoed via a Read of T<n>.yaml) were captured as the impl PR.

    /**
     * Read result.json, validate, apply pr_url enforcement + budget check, and
     * write the final version back. Returns true if a valid result was processed
     * (caller can return), false if no valid result.json exists.
     */
    const processResultJson = (stdout: string): boolean => {
      if (!existsSync(resultPath)) return false;
      let raw: unknown;
      try {
        raw = JSON.parse(readFileSync(resultPath, "utf-8"));
      } catch {
        return false;
      }
      if (!isValidResult(raw)) return false;

      let claudeResult = raw as ExecutorResult;
      if (tokenUsage !== undefined && !claudeResult.token_usage) {
        claudeResult.token_usage = { input: tokenUsage.input, output: tokenUsage.output, model: tokenUsage.model };
      }
      if (tokenUsage !== undefined && claudeResult.cost_usd === undefined) {
        claudeResult.cost_usd = tokenUsage.cost_usd;
      }

      // Refuse terminal_status: in_review without a valid pr_url. Checks:
      //   1. pr_url must be present and non-empty.
      //   2. pr_url owner/repo must match the task's implementation repo.
      //   3. PR head branch must be feature/{featureId}-{taskId} (API-verified).
      let prUrlCtx: Parameters<typeof enforceInReviewRequiresPrUrl>[1];
      try {
        const { owner, repo } = parseGitHubCoords(taskRepoUrl);
        prUrlCtx = { expectedOwner: owner, expectedRepo: repo, featureId, taskId, githubToken: githubToken || undefined };
      } catch {
        prUrlCtx = undefined;
      }
      const enforced = enforceInReviewRequiresPrUrl(claudeResult, prUrlCtx);
      if (enforced.rewritten) {
        emit({
          type: "in_review_refused_no_pr_url",
          task_id: taskId,
          feature_id: featureId,
          blocked_reason: enforced.result.blocked_reason,
        });
      }
      claudeResult = enforced.result;

      if (
        budgetTokens !== undefined &&
        tokenUsage !== undefined &&
        tokenUsage.input + tokenUsage.output > budgetTokens
      ) {
        writeResult(resultPath, {
          terminal_status: "blocked",
          blocked_reason: "budget_exceeded",
          token_usage: tokenUsage,
        });
      } else {
        writeResult(resultPath, claudeResult);
      }

      if (logSinkEnabled && workspaceRoot && taskBranch) {
        flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, stdout, claudeResult.terminal_status, sshKeyPath, emit);
        logFlushed = true;
      }
      return true;
    };

    if (processResultJson(spawnResult.stdout)) {
      // Valid result.json — Layer 1 recovery (finally block) will no-op.
      return;
    }

    // ── 9. Claude did not write result.json ──────────────────────────────────
    // Budget-exceeded: write blocked immediately (deterministic, no recovery side-effects needed).
    if (
      budgetTokens !== undefined &&
      tokenUsage !== undefined &&
      tokenUsage.input + tokenUsage.output > budgetTokens
    ) {
      writeResult(resultPath, {
        terminal_status: "blocked",
        blocked_reason: "budget_exceeded",
        token_usage: tokenUsage,
      });
      if (logSinkEnabled && workspaceRoot && taskBranch) {
        flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, "blocked", sshKeyPath, emit);
        logFlushed = true;
      }
      return;
    }

    // ── 9b. Continuation retry — Claude exited cleanly without writing result ─
    // The headless `-p` session can end on `end_turn` after a sub-skill completes
    // its declared steps, even though the outer skill still has work to do. Give
    // it one focused retry with a short briefing whose only job is to write
    // result.json. Skipped when the first run crashed, was signalled, or hit
    // max-turns — those failure modes won't be helped by another attempt.
    //
    // Review-kind executors have their own recovery path (recovery.recoverReview)
    // that checks GitHub for an already-posted review, so they don't need this.
    const continuationEligible =
      executorKind === "impl" &&
      spawnResult.status === 0 &&
      !spawnResult.signal &&
      !spawnResult.error &&
      !isMaxTurnsExit(spawnResult.stdout);

    if (continuationEligible) {
      const { commitsAhead, workingTreeStatus } = collectGitState(implDir, taskBaseBranch || "main");
      const existingPrUrl = fetchOpenPrUrl(taskRepoUrl, taskRepoBranch, githubToken);

      const continuationBriefing = generateContinuationBriefing({
        taskId,
        featureId,
        taskBranch: taskRepoBranch,
        taskRepoRoot: implDir,
        resultPath,
        taskBaseBranch: taskBaseBranch || "main",
        prUrl: existingPrUrl,
        commitsAhead,
        workingTreeStatus,
      });

      emit({
        type: "executor_continuation_retry",
        task_id: taskId,
        feature_id: featureId,
        had_pr_url: Boolean(existingPrUrl),
      });

      const retryMaxTurns = parseInt(
        process.env.CONTINUATION_MAX_TURNS ?? String(DEFAULT_CONTINUATION_MAX_TURNS),
        10,
      );
      const retryResult = await spawnClaude(continuationBriefing, retryMaxTurns);

      emit({
        type: "executor_continuation_complete",
        task_id: taskId,
        feature_id: featureId,
        exit_code: retryResult.status,
        signal: retryResult.signal ?? null,
      });

      // Replace spawnResult so post-hoc recovery (if needed) uses the latest state
      // for handover.md and emit. tokenUsage is re-extracted from the retry stdout
      // and added to the first-run usage so the audit reflects total tokens spent.
      // Preserve first-run stdout — flushLog and recovery use it for forensics.
      // Concatenate first-run + retry stdout with a separator so the log sink
      // captures both. The retry's stdout alone is the recovery / continuation
      // tail; the first run's is where the real work happened.
      const firstRunStdout = spawnResult.stdout;
      spawnResult = {
        ...retryResult,
        stdout: firstRunStdout + "\n--- continuation retry stdout ---\n" + retryResult.stdout,
      };
      const retryUsage = retryResult.stdout ? extractTokenUsage(retryResult.stdout) : undefined;
      if (retryUsage !== undefined) {
        if (tokenUsage !== undefined) {
          // Sum input/output/cost; keep first-run model when both runs used
          // the same model (the common case). If models differ, emit a
          // pricing_fallback-style warning and use the retry's model so the
          // audit reflects the most-recent run. pricingFallback is true if
          // either run hit it.
          if (tokenUsage.model !== retryUsage.model) {
            emit({
              type: "continuation_model_mismatch",
              task_id: taskId,
              feature_id: featureId,
              first_run_model: tokenUsage.model,
              retry_model: retryUsage.model,
              note: "retry used a different model than first run — audit reflects retry's model",
            });
          }
          tokenUsage = {
            input: tokenUsage.input + retryUsage.input,
            output: tokenUsage.output + retryUsage.output,
            model: tokenUsage.model === retryUsage.model ? tokenUsage.model : retryUsage.model,
            cost_usd: tokenUsage.cost_usd + retryUsage.cost_usd,
            pricingFallback: tokenUsage.pricingFallback || retryUsage.pricingFallback,
          };
        } else {
          tokenUsage = retryUsage;
        }
      }

      if (processResultJson(retryResult.stdout)) {
        emit({ type: "executor_continuation_recovered", task_id: taskId, feature_id: featureId });
        return;
      }

      emit({ type: "executor_continuation_failed", task_id: taskId, feature_id: featureId,
             note: "retry exited without writing result.json — falling through to post-hoc recovery" });
    }

    // No result.json produced — recovery will write one in the finally block.

  } finally {
    // ── Layer 1: post-hoc recovery ────────────────────────────────────────────
    // Runs regardless of how the spawn ended. No-op when result.json has a
    // valid in_review result (Claude finished cleanly). Otherwise: commits
    // uncommitted work, pushes, opens a draft PR, writes handover.md, and
    // writes a blocked result.json.
    await runRecovery({
      spawnResult,
      taskId,
      featureId,
      taskRepoBranch,
      taskRepoPath: implDir,
      taskRepoUrl,
      githubToken,
      sshKeyPath,
      gitAuthorEmail,
      gitAuthorName,
      resultPath,
      tokenUsage: tokenUsage ? { input: tokenUsage.input, output: tokenUsage.output } : undefined,
      kind: executorKind,
      implPrUrl: implPrUrl || undefined,
      taskBaseBranch: taskBaseBranch || undefined,
    });

    // Flush log after recovery (best-effort, uses result.json to determine outcome).
    // Skip if already flushed in the success or budget-exceeded paths above.
    if (!logFlushed && logSinkEnabled && workspaceRoot && taskBranch) {
      let outcome = "unknown";
      try {
        const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as ExecutorResult;
        outcome = raw.terminal_status;
      } catch { /* ignore */ }
      flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult?.stdout ?? "", outcome, sshKeyPath, emit);
    }
  }
}


main().catch((e) => {
  try {
    console.log(JSON.stringify({ type: "fatal_error", details: String(e), at: new Date().toISOString() }));
  } catch { /* last resort */ }
  process.exit(1);
});

/**
 * Claude executor entrypoint — ABI-conformant.
 *
 * Reads ExecutorInput from environment variables, runs two-phase startup,
 * spawns `claude -p`, and writes ExecutorResult to result.json at RESULT_PATH.
 *
 * Formal ABI env vars (from ExecutorInput):
 *   TASK_ID, FEATURE_ID, WORKSPACE_ID, HANDLE
 *   TASK_REPO_URL, TASK_REPO_BRANCH, TASK_BASE_BRANCH
 *   EXECUTOR_WORKDIR, MGMT_REPO_URL
 *   RESULT_PATH, KIND (optional: impl|fix|reviewer|rebase — defaults to impl)
 *   BUDGET_TOKENS (optional)
 *   SSH_PRIVATE_KEY, GITHUB_TOKEN
 *
 * Derived paths (not passed by orchestrator — executor sets them in process.env):
 *   WORKSPACE_ROOT   = ${EXECUTOR_WORKDIR}/mgmt  (management repo clone, read-only)
 *   TASK_REPO_PATH   = ${EXECUTOR_WORKDIR}/impl  (implementation repo)
 *
 * Day-1 single-container extras (not in formal ABI — passed by SubProcessAdapter):
 *   TASK_BRANCH        — management repo feature branch for git commits
 *   GIT_AUTHOR_EMAIL   — for commit identity
 *   GIT_AUTHOR_NAME    — for commit identity
 *   WORKFLOW_LOCAL_PATH — workflow repo root for skills setup
 *   MAX_TURNS          — max claude CLI turns (default: 200)
 *   LOG_SINK_ENABLED   — "1" to flush JSONL log to management repo
 *   MCP_RAG_URL        — optional RAG server URL for MCP registration
 *   FIGMA_PERSONAL_ACCESS_TOKEN — optional Figma MCP
 *   GITNEXUS_MCP_URL   — optional GitNexus code-graph MCP server URL
 *   AGENT_RUNTIME — injected as "1" for agent detection
 */

import { spawn, execSync } from "node:child_process";
import {
  mkdirSync,
  appendFileSync,
  readFileSync,
  writeFileSync,
  existsSync,
  readdirSync,
  rmSync,
  copyFileSync,
  lstatSync,
} from "node:fs";
import { join, dirname } from "node:path";
import { homedir } from "node:os";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { ExecutorResult } from "@workflow/runtime-abi";
import { isValidResult } from "@workflow/runtime-abi";
import { extractTokenUsage } from "./token-usage.js";
import { extractRagQueries } from "./rag-audit.js";
import { extractGitNexusQueries } from "./gitnexus-audit.js";
import { enforceInReviewRequiresPrUrl } from "./enforce-pr-url.js";
import { runRecovery, parseGitHubCoords, isMaxTurnsExit, type SpawnResult } from "./recovery.js";
import {
  generateContinuationBriefing,
  collectGitState,
  fetchOpenPrUrl,
} from "./briefing/continuation-context.js";
import { resolveSSHKey } from "./resolve-ssh-key.js";
import { redactSecrets } from "./redact-secrets.js";
import { buildGitEnv } from "./git-env.js";
import { flushLog } from "./flush-log.js";
import { ensureImplFeatureBranch } from "./impl-feature-branch.js";
import { setupGlobalSettings } from "./setup-global-settings.js";
import { buildBriefing, type BuildBriefingOpts, type BriefingKind } from "./briefing/index.js";

// ── Helpers ───────────────────────────────────────────────────────────────────

function requireEnv(name: string): string {
  const val = process.env[name];
  if (!val) throw new Error(`Required env var ${name} is not set`);
  return val;
}

function emit(event: Record<string, unknown>): void {
  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
}

/**
 * Materialize the implementation repo at taskRepoPath:
 *   - If path exists and origin matches URL: fetch + checkout + pull
 *   - Otherwise: clone fresh
 */
function materializeRepo(
  taskRepoUrl: string,
  taskRepoBranch: string,
  taskRepoPath: string,
  sshKeyPath: string | undefined,
): void {
  const env = buildGitEnv(sshKeyPath);
  const opts = { env, stdio: "pipe" as const };

  if (existsSync(join(taskRepoPath, ".git"))) {
    let originUrl = "";
    try {
      originUrl = execSync(`git -C "${taskRepoPath}" remote get-url origin`, {
        ...opts, encoding: "utf-8",
      }).trim();
    } catch { /* no remote — fall through to clone */ }

    if (originUrl === taskRepoUrl) {
      execSync(`git -C "${taskRepoPath}" fetch origin`, opts);
      // Discard local changes from a previous session before checkout.
      try { execSync(`git -C "${taskRepoPath}" checkout -- .`, opts); } catch { /* ignore */ }
      try {
        execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
      } catch {
        execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
      }
      try {
        execSync(
          `git -C "${taskRepoPath}" pull --ff-only origin "${taskRepoBranch}"`,
          opts,
        );
      } catch {
        emit({ type: "repo_pull_diverged", task_repo: taskRepoPath, branch: taskRepoBranch, note: "ff-only failed — working on checked-out ref without latest origin commits" });
      }
      return;
    }
  }

  // Clone fresh.
  mkdirSync(dirname(taskRepoPath), { recursive: true });
  if (existsSync(taskRepoPath)) {
    rmSync(taskRepoPath, { recursive: true, force: true });
  }
  execSync(`git clone "${taskRepoUrl}" "${taskRepoPath}"`, opts);
  try {
    execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
  } catch {
    execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
  }
}

/**
 * Materialize the management repo at mgmtDir on the task branch.
 * Idempotent: if the dir already contains a valid clone of the same URL,
 * runs fetch + checkout -B <taskBranch> origin/<taskBranch> instead of a fresh clone.
 * Falls back to main if the task branch doesn't exist on origin yet.
 */
function materializeMgmtRepo(
  mgmtRepoUrl: string,
  mgmtDir: string,
  sshKeyPath: string | undefined,
  taskBranch: string,
): void {
  const env = buildGitEnv(sshKeyPath);
  const opts = { env, stdio: "pipe" as const };

  const checkoutTaskBranch = (dir: string): void => {
    try {
      execSync(`git -C "${dir}" checkout -B "${taskBranch}" "origin/${taskBranch}"`, opts);
    } catch (taskBranchErr) {
      // Task branch not on origin yet — fall back to main.
      try {
        execSync(`git -C "${dir}" checkout main`, opts);
      } catch (mainCheckoutErr) {
        emit({ type: "mgmt_repo_checkout_failed", mgmt_dir: dir, branch: "main", details: String(mainCheckoutErr) });
      }
      try {
        execSync(`git -C "${dir}" pull --ff-only origin main`, opts);
      } catch {
        emit({ type: "mgmt_repo_pull_diverged", mgmt_dir: dir, note: "ff-only failed — using checked-out ref", task_branch_err: String(taskBranchErr) });
      }
    }
  };

  if (existsSync(join(mgmtDir, ".git"))) {
    let originUrl = "";
    try {
      originUrl = execSync(`git -C "${mgmtDir}" remote get-url origin`, {
        ...opts, encoding: "utf-8",
      }).trim();
    } catch { /* no remote — fall through to clone */ }

    if (originUrl === mgmtRepoUrl) {
      execSync(`git -C "${mgmtDir}" fetch origin`, opts);
      checkoutTaskBranch(mgmtDir);
      return;
    }
  }

  mkdirSync(dirname(mgmtDir), { recursive: true });
  if (existsSync(mgmtDir)) {
    rmSync(mgmtDir, { recursive: true, force: true });
  }
  execSync(`git clone "${mgmtRepoUrl}" "${mgmtDir}"`, opts);
  checkoutTaskBranch(mgmtDir);
}

/**
 * Turn budget for the E2 continuation retry — the focused re-spawn that runs
 * after a clean exit without result.json. Intentionally low: the retry's only
 * job is to write result.json based on existing branch state, not to do real
 * implementation work. Override via env var if you need more headroom.
 */
const DEFAULT_CONTINUATION_MAX_TURNS = 20;

const TOOLCHAIN_MARKERS: Array<{ file: string; tool: string }> = [
  { file: "yarn.lock",        tool: "yarn"    },
  { file: "pnpm-lock.yaml",   tool: "pnpm"    },
  { file: "bun.lockb",        tool: "bun"     },
  { file: "go.mod",           tool: "go"      },
  { file: "requirements.txt", tool: "python3" },
  { file: "pyproject.toml",   tool: "python3" },
  { file: "Cargo.toml",       tool: "cargo"   },
];

function checkRequiredTools(taskRepoPath: string): string[] {
  const missing: string[] = [];
  const checked = new Set<string>();
  for (const { file, tool } of TOOLCHAIN_MARKERS) {
    if (checked.has(tool)) continue;
    if (!existsSync(join(taskRepoPath, file))) continue;
    checked.add(tool);
    try {
      execSync(`which ${tool}`, { stdio: "pipe" });
    } catch {
      missing.push(tool);
    }
  }
  return missing;
}

function copyWorkspaceClaude(workspaceRoot: string): void {
  const src = join(workspaceRoot, "CLAUDE.md");
  if (!existsSync(src)) return;
  const destDir = join(homedir(), ".claude");
  mkdirSync(destDir, { recursive: true });
  copyFileSync(src, join(destDir, "CLAUDE.md"));
}

function copyDirRecursive(src: string, dest: string): void {
  mkdirSync(dest, { recursive: true });
  for (const entry of readdirSync(src)) {
    const srcPath = join(src, entry);
    const destPath = join(dest, entry);
    const stat = lstatSync(srcPath);
    if (stat.isDirectory()) {
      copyDirRecursive(srcPath, destPath);
    } else if (stat.isFile()) {
      copyFileSync(srcPath, destPath);
    }
  }
}

function setupGlobalSkills(workspaceRoot: string, workflowLocalPath: string): void {
  const globalSkillsDir = join(homedir(), ".claude", "skills");
  if (existsSync(globalSkillsDir)) {
    rmSync(globalSkillsDir, { recursive: true, force: true });
  }
  mkdirSync(globalSkillsDir, { recursive: true });

  const copySkillsFrom = (sourceDir: string): void => {
    if (!existsSync(sourceDir)) return;
    let entries: string[];
    try { entries = readdirSync(sourceDir); } catch { return; }
    for (const entry of entries) {
      const srcPath = join(sourceDir, entry);
      try {
        const stat = lstatSync(srcPath);
        if (!stat.isDirectory()) continue;
        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
      } catch (e) {
        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
      }
    }
  };

  copySkillsFrom(join(workflowLocalPath, "claude", "technical_skills"));
  copySkillsFrom(join(workflowLocalPath, "claude", "workflow_skills"));

  const wsSkillsDir = join(workspaceRoot, ".claude", "skills");
  if (existsSync(wsSkillsDir)) {
    let entries: string[];
    try { entries = readdirSync(wsSkillsDir); } catch { entries = []; }
    for (const entry of entries) {
      if (entry === ".gitignore") continue;
      const srcPath = join(wsSkillsDir, entry);
      try {
        const stat = lstatSync(srcPath);
        if (stat.isSymbolicLink() || !stat.isDirectory()) continue;
        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
      } catch (e) {
        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
      }
    }
  }
}

function writeResult(resultPath: string, result: ExecutorResult): void {
  mkdirSync(dirname(resultPath), { recursive: true });
  writeFileSync(resultPath, JSON.stringify(result), "utf-8");
}

// ── Main ──────────────────────────────────────────────────────────────────────

async function main(): Promise<void> {
  // ── Read formal ABI env vars ────────────────────────────────────────────────
  let taskId: string;
  let featureId: string;
  let taskRepoUrl: string;
  let taskRepoBranch: string;
  let executorWorkdir: string;
  let mgmtRepoUrl: string;
  let resultPath: string;
  let sshKeyPath: string | undefined;
  let githubToken: string;

  try {
    taskId = requireEnv("TASK_ID");
    featureId = requireEnv("FEATURE_ID");
    taskRepoUrl = requireEnv("TASK_REPO_URL");
    taskRepoBranch = requireEnv("TASK_REPO_BRANCH");
    executorWorkdir = requireEnv("EXECUTOR_WORKDIR");
    mgmtRepoUrl = requireEnv("MGMT_REPO_URL");
    resultPath = requireEnv("RESULT_PATH");
    githubToken = process.env.GITHUB_TOKEN ?? "";
    sshKeyPath = resolveSSHKey({ SSH_PRIVATE_KEY: process.env.SSH_PRIVATE_KEY }).sshKeyPath;
  } catch (e) {
    emit({ type: "executor_fatal", details: (e as Error).message });
    process.exit(1);
  }

  const budgetTokensStr = process.env.BUDGET_TOKENS;
  const budgetTokens = budgetTokensStr ? parseInt(budgetTokensStr, 10) : undefined;

  const implDir = join(executorWorkdir, "impl");
  const mgmtDir = join(executorWorkdir, "mgmt");

  // Day-1 single-container extras.
  const workspaceRoot = mgmtDir;
  const taskBranch = process.env.TASK_BRANCH ?? `feature/${featureId}-${taskId}`;
  const gitAuthorEmail = process.env.GIT_AUTHOR_EMAIL ?? "agent@unknown";
  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
  const workflowLocalPath = process.env.WORKFLOW_LOCAL_PATH ?? "";
  const maxTurns = parseInt(process.env.MAX_TURNS ?? "200", 10);
  const logSinkEnabled = process.env.LOG_SINK_ENABLED === "1";
  const mcpRagUrl = process.env.MCP_RAG_URL;
  const figmaToken = process.env.FIGMA_PERSONAL_ACCESS_TOKEN;
  const gitnexusMcpUrl = process.env.GITNEXUS_MCP_URL;
  const implementationModel = process.env.IMPLEMENTATION_MODEL;
  const executorKind = (process.env.EXECUTOR_KIND ?? "impl") as "impl" | "review";
  const implPrUrl = process.env.IMPL_PR_URL ?? "";
  const briefingKind = (process.env.KIND as BriefingKind | undefined) ??
    (executorKind === "review" ? "reviewer" : "impl");

  const runStartIso = new Date().toISOString();

  // ── 1. Two-phase repo materialization ─────────────────────────────────────
  // Phase 1: management repo — checked out to the task branch so $WORKSPACE_ROOT
  // has the current task YAML (on the task branch, not main).
  try {
    materializeMgmtRepo(mgmtRepoUrl, mgmtDir, sshKeyPath, taskBranch);
    process.env.WORKSPACE_ROOT = mgmtDir;
  } catch (e) {
    const details = `mgmt repo materialization failed: ${String(e)}`;
    emit({ type: "executor_fatal", task_id: taskId, details });
    writeResult(resultPath, {
      terminal_status: "failed",
      blocked_reason: `mgmt_repo_materialization_failed: ${String(e)}`,
    });
    process.exit(0);
  }

  // Phase 2: implementation repo
  const taskRepoBaseBranch = process.env.TASK_REPO_BASE_BRANCH ?? "";
  const taskBaseBranch = process.env.TASK_BASE_BRANCH ?? "";
  try {
    materializeRepo(taskRepoUrl, taskRepoBranch, implDir, sshKeyPath);
    process.env.TASK_REPO_PATH = implDir;
  } catch (e) {
    const details = `impl repo materialization failed: ${String(e)}`;
    emit({ type: "executor_fatal", task_id: taskId, details });
    writeResult(resultPath, {
      terminal_status: "failed",
      blocked_reason: `repo_materialization_failed: ${String(e)}`,
    });
    process.exit(0);
  }

  // Ensure `feature/{featureId}` exists on the impl repo remote so PR creation
  // can target it. Uses TASK_REPO_BASE_BRANCH (the repo's root base branch, e.g.
  // "main") as the push source — not TASK_BASE_BRANCH, which is the feature branch
  // itself and cannot be used as its own creation source.
  if (taskRepoBaseBranch) {
    ensureImplFeatureBranch(featureId, taskRepoBaseBranch, implDir, sshKeyPath, emit);
  }

  // ── 2. Toolchain pre-flight check ──────────────────────────────────────────
  const missingTools = checkRequiredTools(implDir);
  if (missingTools.length > 0) {
    const details = `missing tools: ${missingTools.join(", ")}`;
    emit({ type: "preflight_failed", task_id: taskId, feature_id: featureId, details });
    writeResult(resultPath, {
      terminal_status: "blocked",
      blocked_reason: "missing_tool",
      blocked_suggestion: `Install missing tools in the executor image: ${missingTools.join(", ")}`,
    });
    process.exit(0);
  }

  // ── 3. Workspace rules + global skills ─────────────────────────────────────
  if (workspaceRoot) copyWorkspaceClaude(workspaceRoot);
  if (workspaceRoot && workflowLocalPath) setupGlobalSkills(workspaceRoot, workflowLocalPath);
  if (workflowLocalPath) setupGlobalSettings(workflowLocalPath, emit);

  // ── 4. Build briefing (self-contained — reads workspace docs from mgmt repo) ──
  let briefingContent: string;
  try {
    const reviewCycleCount = parseInt(process.env.REVIEW_CYCLE_COUNT ?? "0", 10);
    const maxReviewCycles = parseInt(process.env.MAX_REVIEW_CYCLES ?? "3", 10);
    // Read task YAML from mgmt repo to resolve human-readable repo ID.
    let taskRepo = featureId;
    try {
      const taskYamlPath = join(mgmtDir, "docs", "features", featureId, "tasks", `${taskId}.yaml`);
      const taskYaml = parseYaml(readFileSync(taskYamlPath, "utf-8")) as Record<string, unknown>;
      if (typeof taskYaml["repo"] === "string") taskRepo = taskYaml["repo"];
    } catch { /* fall through to default */ }
    const baseOpts = {
      taskId,
      featureId,
      taskBranch,
      taskRepo,
      taskRepoRoot: implDir,
      workspaceRoot: mgmtDir,
      gitAuthorEmail,
      gitAuthorName,
      implementationModel: implementationModel ?? "claude-sonnet-4-6",
      resultPath,
    };
    let briefingOpts: BuildBriefingOpts;
    if (briefingKind === "reviewer") {
      briefingOpts = {
        kind: "reviewer",
        ...baseOpts,
        prUrl: implPrUrl,
        reviewerModel: implementationModel ?? "claude-sonnet-4-6",
        reviewCycleCount,
        maxReviewCycles,
      };
    } else if (briefingKind === "fix") {
      briefingOpts = {
        kind: "fix",
        ...baseOpts,
        prUrl: implPrUrl,
        mode: "review-fixes",
        reviewUrl: process.env.REVIEW_URL ?? "",
      };
    } else if (briefingKind === "rebase") {
      // Rebase dispatch uses the same fix-briefing infrastructure; mode is
      // forced to "conflict-resolution" inside buildBriefing.
      briefingOpts = {
        kind: "rebase",
        ...baseOpts,
        prUrl: implPrUrl,
        mode: "conflict-resolution",
        taskBaseBranch,
      };
    } else {
      briefingOpts = { kind: "impl", ...baseOpts };
    }
    briefingContent = buildBriefing(mgmtDir, briefingOpts);
  } catch (e) {
    emit({ type: "executor_fatal", task_id: taskId, details: `briefing build failed: ${String(e)}` });
    writeResult(resultPath, {
      terminal_status: "failed",
      blocked_reason: `briefing_build_failed: ${String(e)}`,
    });
    process.exit(0);
  }

  // Append hard-stop rule for missing tools.
  const effectiveBriefing =
    briefingContent +
    `\n\n## Hard stop rule — missing tools\nIf any shell command exits with code 127 ("command not found"), do NOT attempt to install it or work around it. Immediately write \`{"terminal_status":"blocked","blocked_reason":"missing_tool"}\` to \`${resultPath}\` and stop.`;

  // ── 5. Build MCP config ─────────────────────────────────────────────────────
  const mcpArgs: string[] = [];
  if (mcpRagUrl || figmaToken || gitnexusMcpUrl) {
    const mcpConfig: { mcpServers: Record<string, unknown> } = { mcpServers: {} };
    if (mcpRagUrl) {
      mcpConfig.mcpServers["rag-server"] = { type: "sse", url: `${mcpRagUrl}/sse` };
    }
    if (gitnexusMcpUrl) {
      mcpConfig.mcpServers["gitnexus"] = { type: "sse", url: `${gitnexusMcpUrl}/sse` };
    }
    if (figmaToken) {
      mcpConfig.mcpServers["figma"] = {
        type: "stdio",
        command: "npx",
        args: ["-y", "@figma/mcp-server"],
        env: { FIGMA_PERSONAL_ACCESS_TOKEN: figmaToken },
      };
    }
    const mcpConfigPath = `/tmp/mcp-config-${taskId}.json`;
    writeFileSync(mcpConfigPath, JSON.stringify(mcpConfig));
    mcpArgs.push("--mcp-config", mcpConfigPath);
  }

  if (mcpRagUrl) {
    emit({ type: "rag_mcp_registered", url: mcpRagUrl });
  } else {
    emit({ type: "rag_mcp_unavailable", reason: "MCP_RAG_URL not set" });
  }

  // ── 6. Spawn claude — wrapped in try/finally for Layer 1 recovery ───────────
  // PYTHONUSERBASE redirects all `pip install --user` into the executor's own
  // directory, preventing cross-executor pip registration conflicts when two
  // executors work on the same Python repo concurrently (e.g. T2 then T4 on cycle).
  const pybase = join(executorWorkdir, "pybase");
  const claudeEnv = {
    ...buildGitEnv(sshKeyPath),
    CLAUDE_AGENT_RUNTIME: "1",
    RESULT_PATH: resultPath,
    GITHUB_TOKEN: githubToken,
    TASK_REPO_PATH: implDir,
    PYTHONUSERBASE: pybase,
    PATH: `${join(pybase, "bin")}:${process.env.PATH ?? "/usr/local/bin:/usr/bin:/bin"}`,
  };

  /**
   * Spawn `claude -p` with the given briefing and turn limit. Captures stdout
   * into a buffer (also piped to this process's stdout) and installs a watchdog
   * that SIGTERMs the child 30s after it emits its final "result" event.
   */
  async function spawnClaude(briefing: string, turns: number): Promise<SpawnResult> {
    return await new Promise<SpawnResult>((resolve) => {
      const stdoutChunks: string[] = [];

      const child = spawn(
        "claude",
        [
          "-p", briefing,
          "--max-turns", String(turns),
          "--output-format", "stream-json",
          "--verbose",
          "--dangerously-skip-permissions",
          ...(implementationModel ? ["--model", implementationModel] : []),
          ...mcpArgs,
        ],
        { cwd: implDir, env: claudeEnv },
      );

      child.stdout.setEncoding("utf-8");
      child.stderr.setEncoding("utf-8");

      let resultWatchdog: ReturnType<typeof setTimeout> | null = null;
      let stdoutLineBuf = "";
      child.stdout.on("data", (chunk: string) => {
        stdoutChunks.push(chunk);
        process.stdout.write(chunk);
        if (resultWatchdog === null) {
          stdoutLineBuf += chunk;
          const lines = stdoutLineBuf.split("\n");
          stdoutLineBuf = lines.pop() ?? "";
          for (const line of lines) {
            if (line.includes('"type":"result"')) {
              resultWatchdog = setTimeout(() => {
                if (!child.killed) child.kill("SIGTERM");
              }, 30_000);
              break;
            }
          }
        }
      });

      child.stderr.on("data", (chunk: string) => {
        process.stderr.write(chunk);
      });

      child.on("error", (err: Error) => {
        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
        resolve({ stdout: stdoutChunks.join(""), status: null, signal: null, error: err });
      });

      child.on("exit", () => {
        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
        setTimeout(() => {
          if (!child.stdout.destroyed) child.stdout.destroy();
          if (!child.stderr.destroyed) child.stderr.destroy();
        }, 0);
      });

      child.on("close", (code: number | null, signal: string | null) => {
        resolve({ stdout: stdoutChunks.join(""), status: code, signal });
      });
    });
  }

  emit({ type: "claude_spawn", task_id: taskId, feature_id: featureId, max_turns: maxTurns });

  let spawnResult: SpawnResult | undefined;
  let tokenUsage: { input: number; output: number; model: string; cost_usd: number; pricingFallback: boolean } | undefined;
  let logFlushed = false;

  try {
    spawnResult = await spawnClaude(effectiveBriefing, maxTurns);

    emit({
      type: "claude_exit",
      task_id: taskId,
      feature_id: featureId,
      exit_code: spawnResult.status,
      signal: spawnResult.signal ?? null,
    });

    // ── 7. Token audit ────────────────────────────────────────────────────────
    tokenUsage = spawnResult.stdout ? extractTokenUsage(spawnResult.stdout) : undefined;

    if (tokenUsage === undefined) {
      emit({ type: "budget_audit_skipped", task_id: taskId, reason: "usage format not found" });
    } else {
      if (tokenUsage.pricingFallback) {
        emit({ type: "pricing_fallback", task_id: taskId, model: tokenUsage.model, note: "unknown model — Sonnet rates applied" });
      }
      emit({
        type: "budget_audit",
        task_id: taskId,
        feature_id: featureId,
        total_tokens: tokenUsage.input + tokenUsage.output,
        max_tokens: budgetTokens,
      });
    }

    // ── 7a. RAG query audit
    if (spawnResult.stdout) {
      for (const rq of extractRagQueries(spawnResult.stdout)) {
        emit({ type: "rag_query", ...rq });
      }
    }

    // ── 7b. GitNexus query audit
    if (spawnResult.stdout) {
      for (const gq of extractGitNexusQueries(spawnResult.stdout)) {
        emit({ type: "gitnexus_query", ...gq });
      }
    }

    // ── 8. Check for result.json written by Claude ────────────────────────────
    // The pr_url is sourced ONLY from Claude's result.json. The executor does not
    // scrape stdout for GitHub URLs, and does not synthesize an in_review result
    // when Claude exits cleanly without writing result.json — both paths previously
    // produced false-positives where unrelated PR URLs (e.g. the workspace claim PR
    // echoed via a Read of T<n>.yaml) were captured as the impl PR.

    /**
     * Read result.json, validate, apply pr_url enforcement + budget check, and
     * write the final version back. Returns true if a valid result was processed
     * (caller can return), false if no valid result.json exists.
     */
    const processResultJson = (stdout: string): boolean => {
      if (!existsSync(resultPath)) return false;
      let raw: unknown;
      try {
        raw = JSON.parse(readFileSync(resultPath, "utf-8"));
      } catch {
        return false;
      }
      if (!isValidResult(raw)) return false;

      let claudeResult = raw as ExecutorResult;
      if (tokenUsage !== undefined && !claudeResult.token_usage) {
        claudeResult.token_usage = { input: tokenUsage.input, output: tokenUsage.output, model: tokenUsage.model };
      }
      if (tokenUsage !== undefined && claudeResult.cost_usd === undefined) {
        claudeResult.cost_usd = tokenUsage.cost_usd;
      }

      // Refuse terminal_status: in_review without a valid pr_url. Checks:
      //   1. pr_url must be present and non-empty.
      //   2. pr_url owner/repo must match the task's implementation repo.
      //   3. PR head branch must be feature/{featureId}-{taskId} (API-verified).
      let prUrlCtx: Parameters<typeof enforceInReviewRequiresPrUrl>[1];
      try {
        const { owner, repo } = parseGitHubCoords(taskRepoUrl);
        prUrlCtx = { expectedOwner: owner, expectedRepo: repo, featureId, taskId, githubToken: githubToken || undefined };
      } catch {
        prUrlCtx = undefined;
      }
      const enforced = enforceInReviewRequiresPrUrl(claudeResult, prUrlCtx);
      if (enforced.rewritten) {
        emit({
          type: "in_review_refused_no_pr_url",
          task_id: taskId,
          feature_id: featureId,
          blocked_reason: enforced.result.blocked_reason,
        });
      }
      claudeResult = enforced.result;

      if (
        budgetTokens !== undefined &&
        tokenUsage !== undefined &&
        tokenUsage.input + tokenUsage.output > budgetTokens
      ) {
        writeResult(resultPath, {
          terminal_status: "blocked",
          blocked_reason: "budget_exceeded",
          token_usage: tokenUsage,
        });
      } else {
        writeResult(resultPath, claudeResult);
      }

      if (logSinkEnabled && workspaceRoot && taskBranch) {
        flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, stdout, claudeResult.terminal_status, sshKeyPath, emit);
        logFlushed = true;
      }
      return true;
    };

    if (processResultJson(spawnResult.stdout)) {
      // Valid result.json — Layer 1 recovery (finally block) will no-op.
      return;
    }

    // ── 9. Claude did not write result.json ──────────────────────────────────
    // Budget-exceeded: write blocked immediately (deterministic, no recovery side-effects needed).
    if (
      budgetTokens !== undefined &&
      tokenUsage !== undefined &&
      tokenUsage.input + tokenUsage.output > budgetTokens
    ) {
      writeResult(resultPath, {
        terminal_status: "blocked",
        blocked_reason: "budget_exceeded",
        token_usage: tokenUsage,
      });
      if (logSinkEnabled && workspaceRoot && taskBranch) {
        flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, "blocked", sshKeyPath, emit);
        logFlushed = true;
      }
      return;
    }

    // ── 9b. Continuation retry — Claude exited cleanly without writing result ─
    // The headless `-p` session can end on `end_turn` after a sub-skill completes
    // its declared steps, even though the outer skill still has work to do. Give
    // it one focused retry with a short briefing whose only job is to write
    // result.json. Skipped when the first run crashed, was signalled, or hit
    // max-turns — those failure modes won't be helped by another attempt.
    //
    // Review-kind executors have their own recovery path (recovery.recoverReview)
    // that checks GitHub for an already-posted review, so they don't need this.
    const continuationEligible =
      executorKind === "impl" &&
      spawnResult.status === 0 &&
      !spawnResult.signal &&
      !spawnResult.error &&
      !isMaxTurnsExit(spawnResult.stdout);

    if (continuationEligible) {
      const { commitsAhead, workingTreeStatus } = collectGitState(implDir, taskBaseBranch || "main");
      const existingPrUrl = fetchOpenPrUrl(taskRepoUrl, taskRepoBranch, githubToken);

      const continuationBriefing = generateContinuationBriefing({
        taskId,
        featureId,
        taskBranch: taskRepoBranch,
        taskRepoRoot: implDir,
        resultPath,
        taskBaseBranch: taskBaseBranch || "main",
        prUrl: existingPrUrl,
        commitsAhead,
        workingTreeStatus,
      });

      emit({
        type: "executor_continuation_retry",
        task_id: taskId,
        feature_id: featureId,
        had_pr_url: Boolean(existingPrUrl),
      });

      const retryMaxTurns = parseInt(
        process.env.CONTINUATION_MAX_TURNS ?? String(DEFAULT_CONTINUATION_MAX_TURNS),
        10,
      );
      const retryResult = await spawnClaude(continuationBriefing, retryMaxTurns);

      emit({
        type: "executor_continuation_complete",
        task_id: taskId,
        feature_id: featureId,
        exit_code: retryResult.status,
        signal: retryResult.signal ?? null,
      });

      // Replace spawnResult so post-hoc recovery (if needed) uses the latest state
      // for handover.md and emit. tokenUsage is re-extracted from the retry stdout
      // and added to the first-run usage so the audit reflects total tokens spent.
      // Preserve first-run stdout — flushLog and recovery use it for forensics.
      // Concatenate first-run + retry stdout with a separator so the log sink
      // captures both. The retry's stdout alone is the recovery / continuation
      // tail; the first run's is where the real work happened.
      const firstRunStdout = spawnResult.stdout;
      spawnResult = {
        ...retryResult,
        stdout: firstRunStdout + "\n--- continuation retry stdout ---\n" + retryResult.stdout,
      };
      const retryUsage = retryResult.stdout ? extractTokenUsage(retryResult.stdout) : undefined;
      if (retryUsage !== undefined) {
        if (tokenUsage !== undefined) {
          // Sum input/output/cost; keep first-run model when both runs used
          // the same model (the common case). If models differ, emit a
          // pricing_fallback-style warning and use the retry's model so the
          // audit reflects the most-recent run. pricingFallback is true if
          // either run hit it.
          if (tokenUsage.model !== retryUsage.model) {
            emit({
              type: "continuation_model_mismatch",
              task_id: taskId,
              feature_id: featureId,
              first_run_model: tokenUsage.model,
              retry_model: retryUsage.model,
              note: "retry used a different model than first run — audit reflects retry's model",
            });
          }
          tokenUsage = {
            input: tokenUsage.input + retryUsage.input,
            output: tokenUsage.output + retryUsage.output,
            model: tokenUsage.model === retryUsage.model ? tokenUsage.model : retryUsage.model,
            cost_usd: tokenUsage.cost_usd + retryUsage.cost_usd,
            pricingFallback: tokenUsage.pricingFallback || retryUsage.pricingFallback,
          };
        } else {
          tokenUsage = retryUsage;
        }
      }

      if (processResultJson(retryResult.stdout)) {
        emit({ type: "executor_continuation_recovered", task_id: taskId, feature_id: featureId });
        return;
      }

      emit({ type: "executor_continuation_failed", task_id: taskId, feature_id: featureId,
             note: "retry exited without writing result.json — falling through to post-hoc recovery" });
    }

    // No result.json produced — recovery will write one in the finally block.

  } finally {
    // ── Layer 1: post-hoc recovery ────────────────────────────────────────────
    // Runs regardless of how the spawn ended. No-op when result.json has a
    // valid in_review result (Claude finished cleanly). Otherwise: commits
    // uncommitted work, pushes, opens a draft PR, writes handover.md, and
    // writes a blocked result.json.
    await runRecovery({
      spawnResult,
      taskId,
      featureId,
      taskRepoBranch,
      taskRepoPath: implDir,
      taskRepoUrl,
      githubToken,
      sshKeyPath,
      gitAuthorEmail,
      gitAuthorName,
      resultPath,
      tokenUsage: tokenUsage ? { input: tokenUsage.input, output: tokenUsage.output } : undefined,
      kind: executorKind,
      implPrUrl: implPrUrl || undefined,
      taskBaseBranch: taskBaseBranch || undefined,
    });

    // Flush log after recovery (best-effort, uses result.json to determine outcome).
    // Skip if already flushed in the success or budget-exceeded paths above.
    if (!logFlushed && logSinkEnabled && workspaceRoot && taskBranch) {
      let outcome = "unknown";
      try {
        const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as ExecutorResult;
        outcome = raw.terminal_status;
      } catch { /* ignore */ }
      flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult?.stdout ?? "", outcome, sshKeyPath, emit);
    }
  }
}


main().catch((e) => {
  try {
    console.log(JSON.stringify({ type: "fatal_error", details: String(e), at: new Date().toISOString() }));
  } catch { /* last resort */ }
  process.exit(1);
});

/**
 * Briefing generator for the autonomous reviewer executor.
 *
 * Reads task context from the already-cloned management repo (mgmtDir).
 * Instructs the executor to run /review-pr.
 */

import {
  preambleSection,
  identitySection,
  taskContextSection,
  modelSection,
  joinSections,
  readTaskTitle,
} from "./briefing-template.js";

export interface ReviewerBriefingOpts {
  taskId: string;
  featureId: string;
  taskBranch: string;
  taskRepo: string;
  taskRepoRoot: string;
  workspaceRoot: string;
  prUrl: string;
  gitAuthorEmail: string;
  gitAuthorName: string;
  reviewerModel: string;
  resultPath: string;
  /** Current count of in_review log entries — used for cycle-limit display. */
  reviewCycleCount: number;
  /** Max review cycles before escalating. Default: 3. */
  maxReviewCycles: number;
}

/**
 * Generate the per-activation briefing markdown for the reviewer executor.
 *
 * Sections (in order):
 *   1. Preamble — automated context, no interactive session
 *   2. ## Identity
 *   3. ## Your claimed task
 *   4. ## Reviewer context
 *   5. ## What you must do
 *   6. ## Model
 *   7. ## Rules
 */
export function generateReviewerBriefing(mgmtDir: string, opts: ReviewerBriefingOpts): string {
  const {
    taskId,
    featureId,
    taskBranch,
    taskRepo,
    taskRepoRoot,
    workspaceRoot,
    prUrl,
    gitAuthorEmail,
    gitAuthorName,
    reviewerModel,
    resultPath,
    reviewCycleCount,
    maxReviewCycles,
  } = opts;

  const taskTitle = readTaskTitle(mgmtDir, featureId, taskId);

  return joinSections(
    preambleSection(),
    identitySection({ gitAuthorEmail, gitAuthorName }),
    taskContextSection("Your claimed task", {
      taskId,
      featureId,
      taskTitle,
      taskBranch,
      taskRepo,
      taskRepoRoot,
      workspaceRoot,
      prUrl,
    }),
    [
      "## Reviewer context",
      "",
      `Review cycle:     ${reviewCycleCount + 1} of ${maxReviewCycles}`,
      `Result path:      ${resultPath}`,
      `Max cycles (env): MAX_REVIEW_CYCLES=${maxReviewCycles}`,
      "",
      "If review cycle count reaches the max, write `terminal_status: escalate` immediately.",
    ],
    [
      "## What you must do",
      "",
      `Run \`/review-pr\` to evaluate the pull request at \`${prUrl}\`.`,
      "",
      "The skill handles the full reviewer contract:",
      "  1. Check cycle limit — escalate immediately if at/over max.",
      "  2. Read product-spec.md + technical-design.md + tasks.md for context.",
      "  3. Fetch the PR diff.",
      "  4. Wait for CI check-runs to resolve (pass or fail).",
      "  5. Evaluate the diff against the rubric in",
      "     `technical_skills/review-pr/references/review_criteria.md`.",
      "  6. Apply the decision table (CI fail / any 🔴/🟡 → REQUEST_CHANGES; else APPROVE).",
      "  7. Post a GitHub APPROVE or REQUEST_CHANGES review.",
      "  8. If APPROVE: squash-merge the implementation PR via GitHub REST API (before writing result.json).",
      `  9. Write \`result.json\` to \`${resultPath}\` with:`,
      '     `{ "terminal_status": "passed" | "change_requested" | "escalate", ... }`',
      "",
      "Complete all steps without stopping or asking for confirmation.",
    ],
    modelSection(reviewerModel),
    [
      "## Rules",
      "",
      "- Do not ask clarifying questions.",
      "- Use `GITHUB_TOKEN` from the environment for all GitHub API calls.",
      "- Read documents in the specified order before evaluating the diff.",
      "- Every finding must cite the exact file path and line from the diff.",
      "- Every finding must cite the specific rubric criterion that was violated.",
      "- Do not request changes that contradict the approved product spec.",
      `- Always write \`${resultPath}\` as the final step — even on failure.`,
      "- If any shell command exits with code 127 (command not found), write",
      `  \`{"terminal_status":"escalate","verdict":"escalate","confidence":0,"notes":"missing_tool"}\``,
      `  to \`${resultPath}\` and stop immediately.`,
    ],
  );
}

